insert into public.sources (id, slug, name, kind, base_url, note, is_builtin, is_default, is_active, sort_order) values
  ('33333333-3333-4333-8333-000000000001', 'turath', 'موقع تراث', 'turath', 'https://app.turath.io', 'المكتبة الشاملة للتراث الإسلامي — المصدر الافتراضي للتطبيق.', true, true, true, 1),
  ('33333333-3333-4333-8333-000000000002', 'shamela', 'المكتبة الشاملة', 'external', 'https://shamela.ws', 'أصلُ نصوص «تراث» بالمُعرّفات والترقيم نفسها — تُحصد منها كتب السِّيَر وكتب ابن القيم.', true, false, true, 2)
insert into public.scholars (id, slug, name, full_name, era, death_year_hijri, bio, is_active, sort_order) values
  ('11111111-1111-4111-8111-111111111101', 'ibn-al-qayyim', 'ابن القيم', 'محمد بن أبي بكر بن أيوب، شمس الدين ابن قيّم الجوزية', 'القرن الثامن الهجري', 751, 'فقيه ومحدّث وأصولي، من كبار تلاميذ شيخ الإسلام ابن تيمية. اشتهرت كتبه في تزكية النفوس وأعمال القلوب، مثل: مدارج السالكين، وإغاثة اللهفان، وزاد المعاد، والفوائد.', true, 1),
  ('cae5d7ad-e2f6-4932-a98f-27279ca769f6', 'al-dhahabi', 'الذهبي', 'شمس الدين محمد بن أحمد بن عثمان الذهبي', 'القرن الثامن الهجري', 748, 'حافظ الإسلام ومؤرّخه، صاحب «سير أعلام النبلاء» و«تاريخ الإسلام».', true, 2),
  ('256ccd74-6eaf-442a-817a-71fd737f7fad', 'ibn-al-jawzi', 'ابن الجوزي', 'جمال الدين أبو الفرج عبد الرحمن بن علي بن محمد الجوزي', 'القرن السادس الهجري', 597, 'واعظٌ ومؤرّخ ومفسّر، من أكثر العلماء تصنيفاً، وصاحب «صفة الصفوة» و«صيد الخاطر».', true, 3),
  ('491399a5-8258-48a1-9160-100948dba640', 'abu-nuaym', 'أبو نعيم الأصبهاني', 'أحمد بن عبد الله بن أحمد الأصبهاني', 'القرن الخامس الهجري', 430, 'حافظٌ ومحدّث، صاحب «حلية الأولياء وطبقات الأصفياء» في أخبار الزهّاد والعُبّاد.', true, 4)
insert into public.quotes (id, scholar_id, source_id, genre, text, book, volume, page, tags, needs_reference_check, status) values
  ('22222222-2222-4222-8222-000000000001', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'القلب يمرض كما يمرض البدن، وشفاؤه في التوبة والحِمية، ويصدأ كما تصدأ المرآة، وجلاؤه بالذكر، ويَعرى كما يعرى الجسم، وزينته التقوى، ويجوع ويظمأ كما يجوع البدن، وطعامه وشرابه: المعرفة والمحبة والتوكل والإنابة والخدمة.', 'الفوائد', 1, 143, array['القلب', 'التزكية']::text[], false, 'published'),
  ('22222222-2222-4222-8222-000000000002', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'من عرف نفسه اشتغل بإصلاحها عن عيوب الناس.', 'الفوائد', 1, 80, array['محاسبة النفس']::text[], false, 'published'),
  ('22222222-2222-4222-8222-000000000003', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'إضاعة الوقت أشد من الموت؛ لأن إضاعة الوقت تقطعك عن الله والدار الآخرة، والموت يقطعك عن الدنيا وأهلها.', 'الفوائد', 1, 44, array['الوقت']::text[], false, 'published'),
  ('22222222-2222-4222-8222-000000000004', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'ما ضُرب عبدٌ بعقوبةٍ أعظمَ من قسوة القلب.', 'الفوائد', 1, 142, array['القلب']::text[], false, 'published'),
  ('22222222-2222-4222-8222-000000000006', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'العلم نورٌ يقذفه الله في القلب، والمعصية تُطفئ ذلك النور.', 'الجواب الكافي', 1, 132, array['العلم', 'المعاصي']::text[], false, 'published'),
  ('22222222-2222-4222-8222-000000000007', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'الدعاء من أنفع الأدوية، وهو عدو البلاء؛ يدافعه ويعالجه، ويمنع نزوله، ويرفعه أو يخففه إذا نزل.', 'الجواب الكافي', 1, 11, array['الدعاء']::text[], false, 'published'),
  ('22222222-2222-4222-8222-000000000010', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'التوكل نصف الدين، والنصف الثاني: الإنابة؛ فإن الدين استعانةٌ وعبادة.', 'مدارج السالكين', 2, 383, array['التوكل']::text[], false, 'published'),
  ('22222222-2222-4222-8222-000000000011', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'العارف لا يرى له على أحدٍ حقاً، ولا يشهد له على غيره فضلاً؛ ولذلك لا يُعاتب ولا يُطالب.', 'مدارج السالكين', 2, 198, array['الأخلاق']::text[], false, 'published'),
  ('22222222-2222-4222-8222-000000000012', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'جعل الله سبحانه الصبر جواداً لا يكبو، وصارماً لا ينبو، وجنداً غالباً لا يُهزم، وحصناً حصيناً لا يُهدم ولا يُثلم.', 'عدة الصابرين', 1, 5, array['الصبر']::text[], false, 'published'),
  ('22222222-2222-4222-8222-000000000013', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'وهذا التفاوتُ العظيمُ إنما حصلَ بالعلم وثمرته، ولو لم يكن في العلم إلا القُربُ من ربِّ العالمين، والالتحاقُ بعالَم الملائكة، وصحبةُ الملأ الأعلى؛ لكفى به فضلًا وشرفًا، فكيف وعزُّ الدُّنيا والآخرة منوطٌ به ومشروطٌ بحصوله؟', 'مفتاح دار السعادة', 1, 286, array['العلم']::text[], false, 'published'),
  ('22222222-2222-4222-8222-000000000017', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'الشكر: ظهور أثر نعمة الله على لسان عبده ثناءً واعترافاً، وعلى قلبه شهوداً ومحبة، وعلى جوارحه انقياداً وطاعة.', 'مدارج السالكين', 2, 589, array['الشكر']::text[], false, 'published'),
  ('22222222-2222-4222-8222-000000000018', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'من أراد صفاءَ قلبه فليُؤْثِر الله على شهوته.', 'الفوائد', 1, 142, array['القلب', 'المجاهدة']::text[], false, 'published'),
  ('22222222-2222-4222-8222-000000000019', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'أصل كل خير أن تعلم أن ما شاء الله كان، وما لم يشأ لم يكن.', 'الفوائد', 1, 141, array['التوحيد', 'القدر']::text[], false, 'published'),
  ('62937440-eff1-4503-aeaf-7b8f4d3d819b', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'للعبد سترٌ بينه وبين الله وسترٌ بينه وبين الناس؛ فمن هتك الستر الذي بينه وبين الله؛ هتك الله الستر الذي بينه وبين الناس.', 'الفوائد', 1, 44, '{}', false, 'published'),
  ('f003b3b9-671d-4c5a-84d8-864ade511667', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'للعبد ربٌّ هو ملاقيه وبيتٌ هو ساكنُهُ؛ فينبغي له أن يسترضيَ ربَّه قبل لقائه، ويعمُرَ بيته قبل انتقالِهِ إليه.', 'الفوائد', 1, 44, '{}', false, 'published'),
  ('7d2e483e-4df9-47af-9236-17701afd196c', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'الدُّنيا من أولها إلى آخرها لا تُساوي غمَّ ساعة؛ فكيف بغمِّ العُمر؟!', 'الفوائد', 1, 44, '{}', false, 'published'),
  ('06d6fbf2-ea4f-418a-8857-37046ec881d9', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'أعظم الرِّبْح في الدُّنيا أن تشتغل نفسك كلَّ وقتٍ بما هو أولى بها وأنفعُ لها في معادها.', 'الفوائد', 1, 45, '{}', false, 'published'),
  ('9e835cdc-0f64-4be5-810e-be1088227a25', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'يخرُجُ العارفُ من الدُّنيا ولم يقضِ وَطَرهُ من شيئين: بكاؤُهُ على نفسه، وثناؤُهُ على ربِّه.', 'الفوائد', 1, 45, '{}', false, 'published'),
  ('227ec8df-a57e-4ad8-bae6-84705d597b36', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'المخلوق إذا خِفتَه؛ استوحشتَ منه وهربتَ منه، والربُّ تعالى إذا خِفتَه؛ أنستَ به وقَرُبتَ إليه.', 'الفوائد', 1, 45, '{}', false, 'published'),
  ('01789a37-edaa-4df2-8cba-8497d15f26ef', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'لو نفع العلم بلا عمل؛ لما ذمَّ الله سبحانه أحبار أهل الكتاب، ولو نفع العمل بلا إخلاص؛ لما ذمَّ المنافقين.', 'الفوائد', 1, 45, '{}', false, 'published'),
  ('ac2d5132-687b-434d-b2ab-97e4290c0b72', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'دافع الخطرةَ؛ فإن لم تفعل صارت فكرةً؛ فدافع الفكرة؛ فإن لم تفعل صارت شهوةً؛ فحارِبْها؛ فإن لم تفعل صارت عزيمة وهمَّةً؛ فإن لم تُدافعها صارت فعلًا؛ فإن لم تتداركهُ بضدِّه صار عادةً، فيصعُبُ عليك الانتقالُ عنها.', 'الفوائد', 1, 45, '{}', false, 'published'),
  ('5566f384-fb4d-4879-a934-dc8fea5c6d0a', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'لمَّا طلب آدمُ الخلود في الجنة من جانب الشجرة؛ عُوقِب بالخُروج منها، ولما طلب يوسفُ الخروج من السجن من جهة صاحب الرُّؤيا؛ لبث فيه بضع سنين.', 'الفوائد', 1, 46, '{}', false, 'published'),
  ('6e928cb1-2663-4276-bb44-7ea1d2cfd10f', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'من عظُمَ وَقارُ الله في قلبهِ أن يعصيَهُ؛ وَقَّرَهُ الله في قلوب الخلق أن يُذِلُّوه.', 'الفوائد', 1, 49, '{}', false, 'published'),
  ('99a6a126-a313-4738-886a-f3d58c745a18', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'أرضُ الفطرة رحبةٌ قابلةٌ لما يُغرسُ فيها؛ فإن غُرِستْ شجرةُ الإيمان والتَّقْوى أورثتْ حلاوةَ الأبد، وإن غرِستْ شجرة الجهل والهوى فكلُّ الثَّمَرِ مُرٌّ.', 'الفوائد', 1, 50, '{}', false, 'published'),
  ('0650d23a-0e8a-472f-b504-b2957594c509', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'مثالُ تولُّدِ الطاعات ونُموِّها وتزايُدِها؛ كمثل نواةٍ غرستَها، فصارت شجرةً، ثم أثمرتْ، فأكلتَ ثمرها، وغَرستَ نواها، فكلَّما أثمر منها شيءٌ جَنيتَ ثمرَهُ، وغَرستَ نواهُ، وكذلك تَداعِي المعاصي. فليتدَبَّرِ اللبيبُ هذا المثال؛ فمن ثواب الحسنةِ الحسنةُ بعدها، ومن عقوبة السيئةِ السيئةُ بعدها.', 'الفوائد', 1, 50, '{}', false, 'published'),
  ('dfb9d654-5f7e-420b-9ccc-47cbcd3eea4f', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'ليس العجبُ من مملوكٍ يتذلَّلُ لله ويتعبَّدُ له ولا يملُّ من خِدْمَتِهِ مع حاجتِهِ وفقرِهِ إليه، إنَّما العجبُ من مالكٍ يتحبَّبُ إلى مملوكِهِ بصنوفِ إنعامِهِ ويتودَّدُ إليه بأنواع إحسانِهِ مع غِناهُ عنهُ.', 'الفوائد', 1, 50, '{}', false, 'published'),
  ('7ea85f92-1750-41bd-b94d-21520dbf8631', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'فرح إبليسُ بنزول آدمَ من الجنة، وما علم أنَّ هبوط الغائص في اللُّجَّة خلف الدُّرِّ صعودٌ.', 'الفوائد', 1, 51, '{}', false, 'published'),
  ('8a768812-2f58-4505-9697-0b8f707aa73f', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'يا آدم! كنت تدخلُ عليَّ دخولَ الملوك على الملوك، واليوم تدخل عليَّ دخولَ العبيد على الملوك.', 'الفوائد', 1, 51, '{}', false, 'published'),
  ('ff08d23f-8163-4ff7-9ba3-de919affd7c2', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'بحرُ الهوى إذا مَدَّ أغرق، وأخوفُ المَنافذِ على السابح فتحُ البصر في الماء.', 'الفوائد', 1, 55, '{}', false, 'published'),
  ('214587e0-00f6-4950-a785-dfd8b8e5ff06', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'لا بدَّ من سِنَةِ الغفلة ورُقادِ الهوى، ولكن كُنْ خفيفَ النوم؛ فحُرَّاسُ البلد يصيحون: دنا الصباحُ!', 'الفوائد', 1, 55, '{}', false, 'published'),
  ('987e3288-c117-4b86-80a0-54c35d6a6de1', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'نورُ العقل يُضيء في ليل الهوى، فتلُوحُ جادَّةُ الصواب، فيتلمَّحُ البصيرُ في ذلك النور عواقبَ الأمور.', 'الفوائد', 1, 56, '{}', false, 'published'),
  ('2855cf18-bb1b-42ce-97a1-127c971c70b4', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'اخرُجْ بالعزم من هذا الفِنَاء الضَّيِّق المحشُوِّ بالآفات إلى ذلك الفِنَاء الرَّحبِ الذي فيه ما لا عينٌ رأتْ؛ فهناك لا يتعذَّرُ مطلوبٌ ولا يُفْقَدُ محبوبٌ.', 'الفوائد', 1, 56, '{}', false, 'published'),
  ('a572612b-b337-482e-8e59-5c3254b686e5', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'الحربُ قائمةٌ، وأنت أعزلُ في النظَّارةِ؛ فإن حرَّكْتَ رِكابَكَ فللهزيمةِ.', 'الفوائد', 1, 57, '{}', false, 'published'),
  ('0b7fca0f-02ad-413e-9332-86594f0f2b39', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'يا مُكَرَّمًا بحُلَّةِ الإيمانِ بعد حُلَّة العافية وهو يُخْلِقُهُما في مخالفة الخالق! لا تُنْكِرِ السَّلْبَ؛ يَستحقُّ من استعمل نعمةَ المنعِم فيما يكرهُ أن يُسْلَبَها.', 'الفوائد', 1, 57, '{}', false, 'published'),
  ('5920ec35-66d5-4f9b-b278-7e879ed95448', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'كواكِبُ هِمَم العارفين في بُروجِ عَزائمِهِم سيارةٌ ليس فيها زُحَلٌ.', 'الفوائد', 1, 57, '{}', false, 'published'),
  ('6b1bdc16-12f2-42a6-afec-680ebd9b377d', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'يا مَنِ انحرفَ عن جادَّتِهِم! كنْ في أواخرِ الركب، ونَمْ إذا نِمتَ على الطريق؛ فالأميرُ يُراعِي السَّاقَةَ.', 'الفوائد', 1, 58, '{}', false, 'published'),
  ('5a912da3-755b-4be9-9cf8-d57e004e83ee', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'سبَقَ العلمُ بنبوَّةِ موسى وإيمانِ آسية، فَسِيقَ تابوتُهُ إلى بيتها، فجاء طفلٌ منفردٌ عن أمٍّ، إلى امرأةٍ خاليةٍ عن ولدٍ! فللهِ كم في هذه القصة من عبرةٍ! كم ذَبَحَ فرعونُ في طلب موسى من ولدٍ، ولسانُ القَدَرِ يقولُ: لا نُربِّيهِ إلّا في حِجْرِكَ!!', 'الفوائد', 1, 59, '{}', false, 'published'),
  ('c14745ff-f762-4125-baf0-0a579f7e0313', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'رأى بعضُ الحكماءِ بِرْذَوْنًا يُسْقَى عليه، فقال: لو هَمْلَجَ هذا لَرُكِبَ.', 'الفوائد', 1, 60, '{}', false, 'published'),
  ('99cc006d-f73d-43e2-a10b-91d985e6589f', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'القواطعُ مِحَنٌ يتبيَّنُ بها الصادقُ من الكاذبِ؛ فإذا خُضْتَها انقلبتْ أعوانًا لك توصِلُك إلى المقصودِ.', 'الفوائد', 1, 60, '{}', false, 'published'),
  ('a441449f-99ba-4921-ad92-e5bfe0c12088', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'لما رأى المتيقِّظون سطوةَ الدُّنيا بأهلها، وخداعَ الأملِ لأربابهِ، وتملُّك الشيطانِ قيادَ النُّفوس، ورأوا الدولة للنفس الأمَّارةِ؛ لجأوَا إلى حصنِ التضرُّع والالتجاءِ؛ كما يأوي العبدُ المذعورُ إلى حَرَمِ سيِّدِهِ.', 'الفوائد', 1, 63, '{}', false, 'published'),
  ('542f5a27-2a62-40f0-9b5f-d2d25fc46343', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'شهواتُ الدُّنيا كلُعَبِ الخيال، ونظرُ الجاهل مقصورٌ على الظاهر، فأمَّا ذو العقل فيرى ما وراء السِّتْرِ.', 'الفوائد', 1, 64, '{}', false, 'published'),
  ('f76423aa-e4ab-42cf-9ea3-be6eb5316cc6', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'تلمَّحَ القومُ الوجودَ، ففهِموا المقصودَ، فأجمعوا الرحيلَ قبل الرحيل، وشمَّروا للسيرِ في سواءِ السبيل؛ فالناسُ مشتغلون بالفضلاتِ، وهم في قطع الفلواتِ، وعصافيرُ الهوى في وَثاقِ الشبكةِ ينتظرونَ الذبحَ.', 'الفوائد', 1, 64, '{}', false, 'published'),
  ('25ab249d-8999-4848-8e15-e62152d79b65', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'تالله ما كانتِ الأيامُ إلا منامًا؛ فاستيقظوا وقد حصلوا على الظَّفَرِ.', 'الفوائد', 1, 64, '{}', false, 'published'),
  ('40e421c4-5c2f-4cc9-9cb7-a5226824b555', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'ما مضى من الدُّنيا أحلامٌ، وما بقي منها أمانيُّ، والوقتُ ضائعٌ بينَهما.', 'الفوائد', 1, 64, '{}', false, 'published'),
  ('0467d8c8-07d6-4a1c-b509-8fad2c4d027f', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'العملُ بغير إخلاص ولا اقتداءٍ كالمسافر يَملأُ جرابَهُ رملًا يُثْقِلُهُ ولا ينفعُهُ.', 'الفوائد', 1, 66, '{}', false, 'published'),
  ('23a9cc20-239f-47e9-ac9b-c0d88dc93856', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'إذا حملتَ على القلب همومَ الدُّنيا وأثقالهَا، وتهاونتَ بأورادِهِ التي هي قُوتُهُ وحياتُهُ؛ كنتَ كالمسافر الذي يُحمِّلُ دابَّتَهُ فوق طاقتِها، ولا يُوفيها علفَها؛ فما أسرع ما تَقِفُ به!', 'الفوائد', 1, 66, '{}', false, 'published'),
  ('3e0666b9-9eca-4ff6-b814-bfc2fb29ad47', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'الغايةُ: أولٌ في التقديرِ، آخرٌ في الوجودِ، مَبدأٌ في نظرِ العقلِ، منتهًى في منازل الوصول.', 'الفوائد', 1, 67, '{}', false, 'published'),
  ('55b05e3f-34a7-4a59-b638-bfb34fbd9d62', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'ألِفْتَ عَجْزَ العادةِ؛ فلو عَلَتْ بك هِمَّتكَ رُبا المعالي؛ لاحتْ لك أنوارُ العزائم.', 'الفوائد', 1, 67, '{}', false, 'published'),
  ('ca2cf00b-662a-49d8-8087-b7b797488731', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'بينَك وبين الفائزينَ جبلُ الهوى، نزلوا بين يديهِ ونزلْتَ خَلْفَهُ؛ فاطْوِ فَضْلَ منزل تَلْحَقْ بالقوم.', 'الفوائد', 1, 67, '{}', false, 'published'),
  ('8c4a1861-60e7-444e-a54e-ac4489d3a0c5', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'قوةُ الطَّمع في بلوغ الأمل تُوجبُ الاجتهادَ في الطلبِ وشدةَ الحَذَرِ من فَوْتِ المأمول.', 'الفوائد', 1, 68, '{}', false, 'published'),
  ('b53aa7d5-7f7d-4346-9981-045ec2b319ca', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'لا تسألْ سوى مولاكَ؛ فسؤالُ العبدِ غيرَ سيِّدِهِ تشنيعٌ عليه.', 'الفوائد', 1, 68, '{}', false, 'published'),
  ('f01471e0-df1f-4ebd-965e-bff6c6a40803', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'عزلةُ الجاهل فسادٌ، وأما عزلةُ العالِم فَمَعَها حِذاؤُها وسِقاؤُها.', 'الفوائد', 1, 68, '{}', false, 'published'),
  ('676513dc-80ef-4f0e-b2f4-ed02a44e9155', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'إذا خَرَجَتْ مِن فِي عَدُوِّكَ لفظةُ سَفَهٍ فلا تُلْحِقْها بمِثْلِها؛ تُلَقِّحْها، ونَسْلُ الخصام نَسْلٌ مذمومٌ.', 'الفوائد', 1, 68, '{}', false, 'published'),
  ('bdcf0890-e3e7-42d4-91f0-4dcae27ba2c1', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'إذا اقْتَدَحَتْ نارُ الانتقام من نارِ الغَضَبِ؛ ابْتَدَأتْ بإحراقِ القادح.', 'الفوائد', 1, 69, '{}', false, 'published'),
  ('c006b636-a142-436b-9bdf-1d79a4b580ed', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'أوْثِقْ غضبَكَ بسلسلة الحِلْم؛ فإنَّه كلبٌ؛ إنْ أَفْلَتَ أَتلفَ.', 'الفوائد', 1, 69, '{}', false, 'published'),
  ('1d674dca-2701-46af-b798-0ea20ce8755e', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'إذا طَلَعَ نجمُ الهِمَّةِ في ظلام ليل البَطالةِ، ورَدِفَهُ قمرُ العزيمةِ؛ أشرقتْ أرضُ القلبِ بنورِ ربِّها.', 'الفوائد', 1, 69, '{}', false, 'published'),
  ('efd6ce93-8ccd-4380-9812-559cd5ae555d', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'إذا جَنَّ الليلُ تغالبَ النومُ والسهرُ؛ فالخوفُ والشوقُ في مقدَّم عسكرِ اليَقَظَةِ، والكسلُ والتَّواني في كتيبةِ الغفلةِ؛ فإذا حَمَلَ العزمُ حَمَلَ على الميمنةِ، فانهزمتْ جنود التفريطِ؛ فما يَطْلُعُ الفجرُ؛ إلا وقد قُسِمَتِ السُّهْمانُ وبَرَدَتِ الغنيمةُ لأهلِها.', 'الفوائد', 1, 69, '{}', false, 'published'),
  ('3d401b56-c4d6-48fb-9069-179a73139f7f', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'الأرواحُ في الأشباح كالأطيار في الأبراج، وليسَ ما أُعِدَّ للاستفراخ كمن هُيِّئَ للسِّباق.', 'الفوائد', 1, 70, '{}', false, 'published'),
  ('f8d6fe30-94c0-4e50-a017-b9791e2ba1e5', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'من أراد من العمَّالِ أن يَعرِفَ قدرَه عند السلطان فلينظر ماذا يُوليهِ مِن العمل؟ وبأيِّ شُغْلٍ يَشْغَلُهُ؟', 'الفوائد', 1, 70, '{}', false, 'published'),
  ('a7929f85-fe0c-400e-b0b4-c0e042e87386', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'كنْ من أبناءِ الآخرةِ، ولا تكُنْ من أبناءِ الدُّنيا؛ فإنَّ الولد يَتْبَعُ الأمَّ.', 'الفوائد', 1, 70, '{}', false, 'published'),
  ('1b7b3492-663f-4be2-abcd-963f877cb7b7', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'الدُّنيا مجازٌ، والآخرةُ وطنٌ، والأوطارُ إنَّما تُطلَبُ في الأوطان.', 'الفوائد', 1, 71, '{}', false, 'published'),
  ('76bd746b-fafc-43d2-87da-2dcf8646f1e1', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'لا بدَّ أن تَجْذِبَكَ الجواذبُ؛ فاعْرِفْها وكنْ منها على حذرٍ، ولا تَضُرَّكَ الشواغلُ إذا خَلَوْتَ منها وأنتَ فيها.', 'الفوائد', 1, 77, '{}', false, 'published'),
  ('c251bfb5-be04-4ce6-b195-11331a772ec9', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'نورُ الحقِّ أضوأُ من الشمس، فيَحِقُّ لخفافيشِ البصائرِ أن تَعْشَى عنه.', 'الفوائد', 1, 77, '{}', false, 'published'),
  ('6f2a435d-174b-4d92-a14f-aac4498323e9', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'أنفعُ العمل أنْ تغيبَ فيه عن الناس بالإخلاص، وعن نفسك بشهود المِنَّة؛ فلا ترى فيه نفسك ولا ترى الخلق.', 'الفوائد', 1, 80, '{}', false, 'published'),
  ('2c2bc46d-33e3-4aae-906a-4d68207e3e1c', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'دخل الناسُ النارَ من ثلاثة أبوابٍ: باب شبهةٍ أورثتْ شكًّا في دين الله، وباب شهوةٍ أورثتْ تقديمَ الهوى على طاعتِه ومرضاتِه وباب غضبٍ أورثت العدوان على خلقه.', 'الفوائد', 1, 80, '{}', false, 'published'),
  ('5882ee06-3778-4217-be27-beb999430ac5', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'أصولُ الخطايا كلِّها ثلاثةٌ: الكبْرُ: وهو الذي أصار إبليسَ إلى ما أصارهُ، والحِرْصُ: وهو الذي أخرج آدم من الجنَّة، والحسدُ: وهو الذي جَرَّأ أحدَ ابنَي آدمَ على أخيهِ؛ فمنْ وُقِي شَرَّ هذه الثلاثة فقد وُقِيَ الشَّرَّ؛ فالكفرُ من الكِبر، والمعاصي من الحِرْص، والبَغْيُ والظُّلْمُ من الحسد.', 'الفوائد', 1, 80, '{}', false, 'published'),
  ('61192f34-baeb-434a-97c7-b9ee81f8d81d', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'أخسرُ الناسِ صفقةً من اشْتَغَلَ عن الله بنفسِهِ، بل أخسرُ منه من اشْتَغَلَ عن نفسِهِ بالناس.', 'الفوائد', 1, 81, '{}', false, 'published'),
  ('91611368-35fd-46b8-b775-20efb7d49424', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'وأعلى الهِمَم في باب الإرادة أنْ تكونَ الهِمَّةُ متعلقةً بمحبة الله والوقوفِ مع مرادِهِ الدينيِّ الأمريِّ، وأسفلُها أن تكون الهمَّةُ واقفةً مع مرادِ صاحِبها من الله؛ فهو إنما يعبدُهُ لمُرادِهِ منه لا لمرادِ الله منه؛ فالأولُ يريدُ اللهَ ويريدُ مرادَهُ، والثاني يريدُ من الله وهو فارغٌ عن إرادتِهِ.', 'الفوائد', 1, 85, '{}', false, 'published'),
  ('8da45ebf-82c6-433a-87d2-e695c4bd7d9d', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'علماءُ السَّوْءِ جلسوا على بابِ الجنَّةِ يدعونَ إليها الناسَ بأقوالِهِم ويَدْعونَهُم إلى النار بأفعالِهِم؛ فكلَّما قَالتْ أقوالُهُم للناس: هَلُمُّوا! قالتْ أفعالُهُم: لا تَسْمَعوا منهم! فلو كان ما دَعَوْا إليه حقًّا كانوا أولَ المستجيبين له! فهم في الصورة أدِلَّاءُ وفي الحقيقةِ قُطَّاعُ الطريق.', 'الفوائد', 1, 85, '{}', false, 'published'),
  ('d00b8827-e11b-4761-88fb-cd5c913b9833', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'من أحدث قبْلَ السلام بطلَ ما مضى من صلاتِهِ، ومَنْ أفطر قبل غروب الشمس ذهب صيامُهُ ضائعًا، ومن أساءَ في آخر عُمُرِهِ لَقِيَ ربَّه بذلك الوجه.', 'الفوائد', 1, 88, '{}', false, 'published'),
  ('ed2634db-6d12-48ab-81ff-04ffc75a9a91', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'كم جاءَ الثوابُ يَسعَى إليك، فوقف بالبابِ، فردَّه بوَّابُ (سوفَ) و(لعلَّ) و(عسى).', 'الفوائد', 1, 88, '{}', false, 'published'),
  ('04384d1c-9f29-4fad-9a93-32ec79a7d0ab', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'يا مُعَرْقلًا في شَرَكِ الهوى جَمْزةُ عزمٍ وقد خرقت الشبكةَ.', 'الفوائد', 1, 95, '{}', false, 'published'),
  ('37c6995f-7e15-4a77-8b2a-d4d7fb6eaa78', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'لله ملك السماوات والأرض؛ واستقرضَ منك حبَّةً، فبَخِلْتَ بها! وخلقَ سبعة أبحُرٍ، وأحبَّ منك دمعةً، فقَحطَتْ عينُك بها!', 'الفوائد', 1, 95, '{}', false, 'published'),
  ('73fd0ce5-6c51-4251-8380-3b06c17ba6ef', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'إطلاقُ البصر يَنقُشُ في القلب صورةَ المنظور، والقلبُ كعبةٌ، والمعبودُ لا يرضى بمزاحمةِ الأصنام.', 'الفوائد', 1, 95, '{}', false, 'published'),
  ('4ebdb007-4780-476b-a808-170c8c0b973e', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'المعرفة بِساطٌ لا يَطأُ عليه إلا مقرَّبٌ، والمحبَّةُ نشيدٌ لا يطربُ عليه إلا مُحِبٌّ مُغْرَمٌ.', 'الفوائد', 1, 96, '{}', false, 'published'),
  ('c4a993ef-f1fd-4482-9187-c93a70fb794f', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'الحبُّ غديرٌ في صحراءَ، ليستْ عليه جادَّةٌ؛ فلهذا قلَّ وارِدُهُ.', 'الفوائد', 1, 96, '{}', false, 'published'),
  ('4d5e3485-3e68-4cd1-9d41-5975d9fe6f2a', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'ليس للعابد مستراحٌ إلا تحت شجرة طُوبى، ولا للمحبِّ قرارٌ إلَّا يومَ المزيد.', 'الفوائد', 1, 96, '{}', false, 'published'),
  ('cb8d21c5-3089-4d66-afcd-2e8daa6af349', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'تالله ما عَدا عليك العدوُّ إلَّا بعد أن تولَّى عنك الوليُّ؛ فلا تظنَّ أن الشيطان غلب، ولكن الحافظ أعرض.', 'الفوائد', 1, 97, '{}', false, 'published'),
  ('738c78f9-f828-4da8-827b-1e8214da649f', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'احذرْ بنفسِك! فما أصابك بلاءٌ قط إلَّا منها، ولا تُهادِنْها! فوالله ما أكرمَها من لم يُهِنْها، ولا أعزَّها من لم يُذِلَّها، ولا جَبَرَها من لم يَكسِرْها، ولا أراحَهَا من لم يُتْعِبْها، ولا أمَّنها من لمْ يُخوِّفها، ولا فرَّحها من لم يُحزِنْها.', 'الفوائد', 1, 97, '{}', false, 'published'),
  ('67578160-02e8-446a-b634-49bb875307e5', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'سبحان الله! ظاهرُك متجمِّلٌ بلباس التَّقوى، وباطنُك باطيةٌ لخمر الهوى، فكلَّما طيَّبتَ الثوبَ فاحتْ رائحةُ المسكِر من تحته، فتباعدَ منك الصادقون، وانحاز إليك الفاسقون.', 'الفوائد', 1, 97, '{}', false, 'published'),
  ('4dc736b9-5e2e-40e7-a275-5bc31e00508f', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'يدخُل عليك لصُّ الهوى وأنت في زاوية التعبُّد، فلا يَرى منك طردًا له، فلا يزالُ بك حتى يُخرِجك من المسجد.', 'الفوائد', 1, 97, '{}', false, 'published'),
  ('c54b10c1-6579-4da3-a93c-fa9ccaf60237', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'اجتنبْ من يُعادِي أهلَ الكتاب والسُّنَّة لئلَّا يُعْدِيك خُسرانُه.', 'الفوائد', 1, 105, '{}', false, 'published'),
  ('4283e8bb-f072-45de-a2b6-fe2e61ca6087', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'احترزْ من عدُوَّين هلك بهما أكثرُ الخلق: صادٍّ عن سبيل الله بشُبُهاتِه وزُخْرُفِ قوله، ومفتونٍ بدُنياه ورئاستِهِ.', 'الفوائد', 1, 105, '{}', false, 'published'),
  ('0cf60e77-0084-430c-9673-3343bf17ac4b', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'قد علمَ المشتري بعيبِ السِّلْعة قبل أن يشتريها فسلِّمْها ولك الأمانُ من الرد.', 'الفوائد', 1, 107, '{}', false, 'published'),
  ('fa79ba4b-433b-4227-9973-3908a3a51aa7', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'يا من هو من أرباب الخبرة! هل عرفتَ قيمةَ نفسِك؟ إنما خُلِقت الأكوانُ كلُّها لك.', 'الفوائد', 1, 109, '{}', false, 'published'),
  ('f1192fb1-18db-4fdf-8154-bdb07d8dbe79', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'متى رُمتَ طلبي فاطلُبْني عندك، واطلُبْني منك تجدْني قريبًا، ولا تطلُبْني من غيرك فأنا أقربُ إليك منه.', 'الفوائد', 1, 110, '{}', false, 'published'),
  ('cdadd060-ace0-45bb-a52f-7e8ef0e18f57', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'لو عرفتَ قدْرَ نفسِك عندنا ما أهنتَها بالمعاصي، إنما أبْعَدْنا إبليسَ إذْ لم يَسجُدْ لك وأنتَ في صُلبِ أبيك؛ فواعجبًا! كيف صالحتَهُ وتركتَنا؟!', 'الفوائد', 1, 110, '{}', false, 'published'),
  ('5ae40ec8-cbae-4520-bf63-152e41a72c2d', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'مَلَؤوا مراكبَ القلوب متاعًا لا يَنفقُ إلا على الملك، فلما هَبَّتْ رياحُ السَّحرِ أقلعتْ تلك المراكبُ، فما طلعَ الفجرُ إلَّا وهي بالمِيناء.', 'الفوائد', 1, 111, '{}', false, 'published'),
  ('87bf5498-6f04-4d17-9bc1-502d05ee6441', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'فَرَّغَ القومُ قُلوبَهم من الشواغل، فضُرِبَتْ فيها سُرادِقاتُ المحبة، فأقاموا العيونَ تَحْرُسُ تارةً وتَرُشُّ أخرى.', 'الفوائد', 1, 111, '{}', false, 'published'),
  ('4cd18bc5-ce86-4136-b57c-1896386b786f', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'هانَ سَهَرُ الحُرَّاسِ لمَّا علموا أن أصواتَهم بسَمْعِ الملك.', 'الفوائد', 1, 112, '{}', false, 'published'),
  ('11d6e603-1bf3-48e5-b95c-36747c6c09f4', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'الجنَّةُ تَرضَى منك بأداء الفرائض، والنارُ تَندفعُ عنك بتَرْكِ المعاصي، والمحبَّهُ لا تَقنَعُ منك إلا ببذل الرُّوح.', 'الفوائد', 1, 113, '{}', false, 'published'),
  ('f221971e-24d1-46fe-8ec6-d95d5458c129', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'عَلَّمْتَ كلبَك فهو يترُكُ شهوتَه في تناوُل ما صادَهُ؛ احترامًا لنعمتك، وخوفًا من سطوتك، وكم عَلَّمك معلِّمُ الشرعِ وأنتَ لا تقبلُ.', 'الفوائد', 1, 113, '{}', false, 'published'),
  ('6c92aef8-902e-4359-8203-023f06bfff64', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'حُرِّم صيدُ الجاهلِ والممسكِ لنفسه؛ فما ظنُّ الجاهلِ الذي أعمالُهُ لهوى نفسِه.', 'الفوائد', 1, 113, '{}', false, 'published'),
  ('a32c284b-b083-4d24-a059-ae22bdc47841', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'لمَّا صَادَ الكلبُ لربِّهِ أُبِيحَ صيدُهُ، ولما أمْسَكَ على نفسه حَرُمَ ما صادَهُ.', 'الفوائد', 1, 114, '{}', false, 'published'),
  ('41ca887f-6c0b-4047-9f60-a557e1049d3f', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'مصدرُ ما في العبد من الخير والشرِّ والصفاتِ الممدوحة والمذمومة من صفة المُعطِي المانع؛ فهو سبحانه يُصرِّفُ عبادَه بين مقتضى هذين الاسمين؛ فحظُّ العبدِ الصادقِ من عبوديَّتِهِ بهما الشُّكْرُ عند العطاء، والافتقارُ عند المنع؛ فهو سبحانه يُعطِيه ليشكُرهُ، ويَمنعُهُ ليفتقرَ إليه، فلا يَزالُ شكورًا فقيرًا.', 'الفوائد', 1, 114, '{}', false, 'published'),
  ('1ad3ff26-4d03-449a-bfa1-7a225e19c399', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'أصولُ المعاصي كلِّها -كبارها وصغارها- ثلاثةٌ: تعلُّقُ القلبِ بغير الله، وطاعةُ القوة الغضبيَّة، والقوة الشهوانيَّةِ. وهي: الشركُ، والظلمُ، والفواحشُ. فغايةُ التعلُّق بغير الله: الشركُ وأن يُدْعى معه إلهٌ آخرُ، وغايةُ طاعة القوَّة الغضبيَّة: القتلُ، وغايةُ طاعة القوَّةِ الشهوانيَّة: الزِّنى.', 'الفوائد', 1, 116, '{}', false, 'published'),
  ('6ea4ef34-339a-4e0b-b58e-e2f109f11865', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'قسوةُ القلب من أربعة أشياء إذا جاوزتْ قدرَ الحاجة: الأكل، والنوم، والكلام، والمخالطة.', 'الفوائد', 1, 142, '{}', false, 'published'),
  ('dc5a8947-eef3-4d1d-80bf-da8414c28ead', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'كما أن البدن إذا مرض لم ينفع فيه الطعامُ والشرابُ؛ فكذلك القلبُ إذا مرض بالشهوات لم تَنْجَعْ فيه المواعظُ.', 'الفوائد', 1, 142, '{}', false, 'published'),
  ('5251b6ff-fd7a-48ca-980e-6d27977efb54', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'القلوب المتعلقةُ بالشهوات محجوبةٌ عن الله بقدر تعلُّقها بها.', 'الفوائد', 1, 142, '{}', false, 'published'),
  ('c24301c4-a0c7-420f-8e84-20a867ebbeb5', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'القلوب آنيةُ الله في أرضه؛ فأحبُّها إليه أرقُّها وأصلبها وأصفاها.', 'الفوائد', 1, 142, '{}', false, 'published'),
  ('20694f8d-44a6-4484-aecf-234ae716a481', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'شَغلوا قلوبهم بالدُّنيا، ولو شَغلوها بالله والدار الآخرة لجالتْ في معاني كلامه وآياته المشهودة، ورَجعتْ إلى أصحابها بغرائب الحكم وطُرَفِ الفوائد.', 'الفوائد', 1, 142, '{}', false, 'published'),
  ('2321bdda-f7d3-4f03-befb-d9507f96c2eb', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'إذا غُذِيَ القلبُ بالتذكُّر، وسُقِي بالتفكُر، ونُقِّيَ من الدَّغل؛ رأى العجائبَ وأُلهِمَ الحكمةَ.', 'الفوائد', 1, 143, '{}', false, 'published'),
  ('b9f4ddc9-053a-4898-90d6-9322a16696a9', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'ليس كلُّ من تَحلَّى بالمعرفة والحكمة وانتحلها كان من أهلها، بل أهلُ المعرفة والحكمة الذين أَحيَوا قلوبَهم بقتل الهوى، وأما من قتل قلبه فأحيا الهوى؛ فالمعرفة والحكمة عاريَّةٌ على لسانه.', 'الفوائد', 1, 143, '{}', false, 'published'),
  ('84d54f96-16cb-40fb-b253-90525e0cac3d', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'خَرابُ القلبِ من الأمن والغفلة، وعِمارتُهُ من الخشية والذِّكْرِ.', 'الفوائد', 1, 143, '{}', false, 'published'),
  ('e0f526cd-b10c-4132-8160-6bdc326e3545', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'إذا زَهِدَت القلوبُ في موائد الدُّنيا؛ قعدتْ على مَوائدِ الآخرة بين أهل تلك الدعوة، وإذا رَضِيتْ بموائد الدُّنيا؛ فَاتَتْها تلك الموائدُ.', 'الفوائد', 1, 143, '{}', false, 'published'),
  ('d21e7a44-09db-4f53-9f5a-622113368ebf', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'الشوقُ إلى الله ولقائه نسيمٌ يَهُبُّ على القلب يُرَوِّحُ عنه وَهَجَ الدُّنيا.', 'الفوائد', 1, 143, '{}', false, 'published'),
  ('5a4c0be9-77be-4b30-9193-1097c7e4339c', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'من وَطَّنَ قلبَه عند ربِّه سكنَ واستراح، ومن أرسله في الناس اضطربَ واشتد به القلقُ.', 'الفوائد', 1, 143, '{}', false, 'published'),
  ('019f7376-61a2-4158-a215-0fa45b0a0cf6', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'لا تَدخلُ محبةُ الله في قلب فيه حبُّ الدُّنيا إلا كما يدخل الجملُ في سَمِّ الإبرة.', 'الفوائد', 1, 143, '{}', false, 'published'),
  ('0108ccda-6e0e-4cf8-bda2-c87ee7cd5626', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'وإذا أحبَّ الله عبدًا اصطنَعه لنفسِه، واجتباهُ لمحبَّتِهِ، واستخلصه لعبادته، فشَغلَ همَّهُ به، ولسانهُ بذكره، وجوارحَهُ بخدمته.', 'الفوائد', 1, 143, '{}', false, 'published'),
  ('e4831b82-6b21-4d49-92b6-5b19af12ff48', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'المتوكِّلُ لا يسألُ غيرَ الله، ولا يرُدُّ على الله، ولا يدَّخِرُ مع الله.', 'الفوائد', 1, 144, '{}', false, 'published'),
  ('3c54e291-2cb9-4716-bbc2-2bf42b2338aa', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'من شُغل بنفسه شُغِلَ عن غيره، ومن شُغِل بربِّه شُغِل عن نفسه.', 'الفوائد', 1, 144, '{}', false, 'published'),
  ('7a766f52-73c7-40c7-bdd5-460762830a67', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'الإخلاصُ: هو ما لا يعلمه مَلَكٌ فيكتبه، ولا عدوُّ فيُفسِدهُ، ولا يُعجَبُ به صاحبه فيُبطِله.', 'الفوائد', 1, 144, '{}', false, 'published'),
  ('c4f53e07-77e3-4781-ac50-50524a61206a', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'للقلب ستة مواطنَ يجولُ فيها لا سابعَ لها؛ ثلاثةٌ سافلة، وثلاثةٌ عاليةٌ: فالسافلةُ: دنيا تتزيَّنُ له، ونفسٌ تحدِّثُه، وعدوٌّ يوسوسُ له. فهذه مواطنُ الأرواح السافلة التي لا تزالُ تجولُ فيها. والثلاثة العاليةُ: علمٌ يتبيَّنُ له، وعقلٌ يرشدُه، وإلهٌ يعبدُه. والقلوب جوَّالةٌ في هذه المواطن.', 'الفوائد', 1, 144, '{}', false, 'published'),
  ('eceed1c8-4d7f-4a5f-9687-ddcba5e2bd68', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'لا يشمُّ عبدٌ رائحةَ الصدق و[هو] يُداهِنُ نفسَه أو يُداهِنُ غيرَه.', 'الفوائد', 1, 145, '{}', false, 'published'),
  ('d2b80da8-1f70-40a9-899f-965dd0d32ad1', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'إذا أراد الله بعبدٍ خيرًا جعله معترفًا بذنبه ممسكًا عن ذنب غيره، جوادًا بما عنده زاهدًا فيما عند غيره، محتملًا لأذى غيره. وإنْ أراد به شرًّا عكس ذلك عليه.', 'الفوائد', 1, 145, '{}', false, 'published'),
  ('e2c6e45e-5295-46e8-89e1-526829c4b767', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'الهمَّةُ العليَّةُ لا تزالُ حائمةً حول ثلاثة أشياء: تعرُّفٌ لصفةٍ من الصفات العليا تزدادُ بمعرفتها محبةً وإرادةً، وملاحظةٌ لمِنَّةٍ تزدادُ بملاحظتها شُكرًا وطاعة، وتذكُّرٌ لذنبٍ تزدادُ بتذكُّرِهِ توبةً وخشية؛ فإذا تعلَّقتِ الهمةُ بسوى هذه الثلاثة جالتْ في أودية الوساوس والخطرات.', 'الفوائد', 1, 145, '{}', false, 'published'),
  ('d437c958-a350-47d0-9ae0-b6beab3adc76', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'من عَشِقَ الدُّنيا نظرتْ إلى قدرها عنده، فصيَّرتْه من خَدَمِها وعبيدِها وأذلَّتْه. ومن أعرض عنها نظرتْ إلى كبر قدره، فخدمته وذلَّت له.', 'الفوائد', 1, 145, '{}', false, 'published'),
  ('0fae74c2-73a2-44c6-b541-f38ea054c80e', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'العقولُ المؤيَّدةُ بالتوفيق تَرى أنَّ ما جاء به الرسولُ هو الحقُّ الموافقُ للعقل والحكمة، والعقولُ المضروبة بالخِذْلانِ ترى المعارضة بين العقل والنقل وبين الحكمة والشرع.', 'الفوائد', 1, 157, '{}', false, 'published'),
  ('ae36009e-0e2c-4eec-9d02-a3e62a6eb8fb', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'أقربُ الوسائل إلى الله ملازمةُ السُّنَّة والوقوفُ معها في الظاهر والباطن، ودوامُ الافتقار إلى الله، وإرادةُ وجهه وحده بالأقوال والأفعال. وما وصلَ أحدٌ إلى الله إلَّا من هذه الثلاثة، وما انقطع عنه أحدٌ إلّا بانقطاعه عنها أو عن أحدها.', 'الفوائد', 1, 157, '{}', false, 'published'),
  ('cbdcc260-34b8-4fb6-9fe0-22205bbb3479', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'إذا استغنى الناسُ بالدُّنيا فاستغنِ أنت بالله، وإذا فرحوا بالدُّنيا فافرح أنت بالله، وإذا أَنِسُوا بأحبابهم فاجعلْ أنسَك بالله، وإذا تعرَّفوا إلى ملوكهم وكبرائهم وتقربوا إليهم لينالوا بهم العزَّ والرفعة؛ فتعرَّفْ أنت إلى الله وتودَّدْ إليه؛ تنالُ بذلك غاية العز والرفعة.', 'الفوائد', 1, 170, '{}', false, 'published'),
  ('7023a088-f29c-4c28-a694-f4ed873d195d', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'اطلبْ قلبك في ثلاثة مواطن: عند سماع القرآن، وفي مجالِس الذِّكر، وفي أوقات الخلوة؛ فإن لم تجدهُ في هذه المواطن فسَلِ الله أن يَمُنَّ عليك بقلبٍ؛ فإنه لا قلبَ لك.', 'الفوائد', 1, 218, '{}', false, 'published'),
  ('f50e7ce5-fae4-48d8-9e19-7ab9e2ae8467', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'السَّنة شجرةٌ، والشهور فروعها، والأيام أغصانها، والساعات أوراقها، والأنفاس ثمرها، فمن كانت أنفاسه في طاعته فثمرة شجرته طيبةٌ، ومن كانت في معصيةٍ فثمرته حنظلٌ، وإنما يكون الجَدَادُ يوم المعاد؛ فعند الجَدَاد يتبينُ حلو الثمار من مُرّها.', 'الفوائد', 1, 240, '{}', false, 'published'),
  ('74832c56-dbcc-4b3a-bc2c-a282955fa252', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'والإخلاص والتوحيد شجرةٌ في القلب؛ فروعها الأعمال، وثمرها طيب الحياة في الدنيا والنعيم المقيم في الآخرة، وكما أن ثمار الجنة لا مقطوعةٌ ولا ممنوعةٌ؛ فثمرة التوحيد والإخلاص في الدُّنيا كذلك.', 'الفوائد', 1, 240, '{}', false, 'published'),
  ('7cdf8662-dea3-4335-bda3-cc4d221b05b4', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'سئل سهل التستري: الرجل يأكل في اليوم أكلةً؟ قال: أكل الصديقين. قيل له: فأكلتين؟ قال: أكل المؤمنين. قيل له: فثلاث أكلاتٍ؟ فقال: قل لأهله يَبنُوا له مِعْلفًا.', 'الفوائد', 1, 261, '{}', false, 'published'),
  ('44ce5918-ef3a-49fe-b3cb-952ba315656d', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'العارف في الأرض ريحانةٌ من رياحين الجنة، إذا شمَّها المريد اشتاقتْ نفسُه إلى الجنة.', 'الفوائد', 1, 262, '{}', false, 'published'),
  ('02314136-86a9-4703-be20-ba1859c24d1b', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'لا تُبدِ فاقةً إلى غيري فأضاعفَها عليك، مكافأةً لخروجك عن حدك في عبوديتك.', 'الفوائد', 1, 285, '{}', false, 'published'),
  ('5d65464a-436f-4e12-b3fc-0e329f30d811', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'ابتليتُك بالفقر لتصير ذهبًا خالصًا؛ فلا تَزِيْفَنَّ بعد السبك.', 'الفوائد', 1, 285, '{}', false, 'published'),
  ('f986eb89-29e7-47ec-9131-1d9d2d0d4059', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'الطلب لِقاحُ الإيمان؛ فإذا اجتمع الإيمان والطلب أثمرا العملَ الصالح.', 'الفوائد', 1, 289, '{}', false, 'published'),
  ('e1784287-ae88-4eb9-a33e-2fa5594edaef', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'وحسن الظن بالله لِقاح الافتقار والاضطرار إليه؛ فإذا اجتمعا أثمرا إجابةَ الدعاء.', 'الفوائد', 1, 289, '{}', false, 'published'),
  ('60e858a4-0c74-4f52-9353-191ab1aa6b26', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'والخشية لِقاح المحبة؛ فإذا اجتمعا أثمرا امتثالَ الأوامر واجتناب المناهي.', 'الفوائد', 1, 289, '{}', false, 'published'),
  ('9b1cbbc8-4365-4561-a946-bbaa671842b9', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'وصحة الاقتداء بالرسول لِقاح الإخلاص؛ فإذا اجتمعا أثمرا قبولَ العمل والاعتداد به.', 'الفوائد', 1, 289, '{}', false, 'published'),
  ('fe22d322-1922-4614-b005-1218bf37dd56', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'والحلم لِقاح العلم؛ فإذا اجتمعا حصلتْ سيادة الدنيا والآخرة وحصل الانتفاع بعلم العالم، وإن انفرد أحدهما عن صاحبه فات النفع والانتفاع.', 'الفوائد', 1, 290, '{}', false, 'published'),
  ('14451f84-db2c-46c2-8b47-94e68cf996a8', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'والعزيمة لِقاحُ البصيرة؛ فإذا اجتمعا نال صاحبهما خيرَ الدنيا والآخرة، وبلغتْ به همتُه من العلياء كلَّ مكان؛ فتخلُّف الكمالاتِ إما من عدم البصيرة وإما من عدم العزيمة.', 'الفوائد', 1, 290, '{}', false, 'published'),
  ('4048db07-0825-4ec2-9c1a-d779a3b8faff', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'وحسن القصد لِقاحٌ لصحة الذهن؛ فإذا فُقِدا فُقِد الخيرُ كلُّه، وإذا اجتمعا أثمرا أنواع الخيرات.', 'الفوائد', 1, 290, '{}', false, 'published'),
  ('7e00d5b1-f6ea-46e4-a87e-8e6a550dff26', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'وصحة الرأي لِقاح الشجاعة؛ فإذا اجتمعا كان النصرُ والظفر، وإن فُقِدا فالخذلان والخيبة، وإن وُجد الرأي بلا شجاعة فالجبنُ والعجز، وإن حصلت الشجاعة بلا رأي؛ فالتهور والعطب.', 'الفوائد', 1, 290, '{}', false, 'published'),
  ('ff3397f7-2de6-4f8a-ba7f-e60c8a01bd54', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'والصبر لِقاح البصيرة؛ فإذا اجتمعا فالخير في اجتماعهما؛ قال الحسن: إذا شئتَ أن ترى بصيرًا لا صبرَ له رأيتَه، وإذا شئت أن ترى صابرًا لا بصيرةَ له رأيتَه، فإذا رأيتَ صابرًا بصيرًا فذاك.', 'الفوائد', 1, 290, '{}', false, 'published'),
  ('d3b8a69e-cdcd-4e6a-aa7a-f38226ffd408', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'والنصيحة لِقاح العقل، فكلما قويتِ النصيحةُ قوي العقلُ واستنار.', 'الفوائد', 1, 290, '{}', false, 'published'),
  ('935d96f9-c22c-433c-9b5c-8333f9317653', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'والتذكُّر والتفكر كل منهما لِقاح الآخر، إذا اجتمعا أنتجا الزهدَ في الدنيا والرغبة في الآخرة.', 'الفوائد', 1, 290, '{}', false, 'published'),
  ('750fe8e7-f6e5-45fd-87d0-48385984e820', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان أبو الدرداء إذا كتب إلى سلمان - أو سلمان كتب إلى أبي الدرداء - كتب إليه يذكره بآية الصحفة.', 'حلية الأولياء', 1, 224, '{}', false, 'published'),
  ('62436498-c33c-4f4f-bfd4-4f71e2bfe8f9', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'فكان أبو موسى يتوخى ذلك اليوم الحار الشديد الحر الذي يكاد ينسلخ فيه الإنسان فيصومه.', 'حلية الأولياء', 1, 260, '{}', false, 'published'),
  ('ea928a4b-b0c2-4069-869a-d5cc0c7ed7d2', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان ابن عمر إذا اشتد عجبه بشيء من ماله قربه لربه ﷿.', 'حلية الأولياء', 1, 294, '{}', false, 'published'),
  ('d14a95ac-c7c5-4e37-a197-5d1b16adaa7a', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان ابن عمر إذا مر بربعهم - وقد هاجر منه - غمض عينيه ولم ينظر إليه ولم ينزله قط.', 'حلية الأولياء', 1, 303, '{}', false, 'published'),
  ('8852d4d6-c085-4c0e-96ae-a059abc97b84', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان ابن عمر كلما استيقظ من الليل صلى.', 'حلية الأولياء', 1, 304, '{}', false, 'published'),
  ('a34a3709-553b-4208-bf64-cdff86a97751', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان عبد الله بن الزبير إذا قام في الصلاة كأنه عود، وكان يقول ذلك من الخشوع في الصلاة.', 'حلية الأولياء', 1, 335, '{}', false, 'published'),
  ('eb0410df-6a2b-44ec-aad8-a033e3c1d263', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان ابن الزبير إذا صلى كأنه كعب راتب.', 'حلية الأولياء', 1, 335, '{}', false, 'published'),
  ('3c9fa184-1e79-4304-a6ce-4bd99f25ae04', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان ابن الزبير يواصل سبعة أيام ويصبح يوم السابع وهو أليثنا.', 'حلية الأولياء', 1, 335, '{}', false, 'published'),
  ('0c87f4b1-b15a-4918-92db-364f50b42914', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان الأسود يختم القرآن في رمضان في كل ليلتين، وكان ينام بين المغرب والعشاء وكان يختم القرآن في غير رمضان في كل ست ليال.', 'حلية الأولياء', 2, 103, '{}', false, 'published'),
  ('86e01a13-e6f0-43d7-a1ff-470722b7a1cd', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان الربيع بن خيثم إذا سجد كأنه ثوب مطروح، فتجئ العصافير فتقع عليه.', 'حلية الأولياء', 2, 114, '{}', false, 'published'),
  ('c741b910-6c40-4c9f-ad29-17f94df9c4c8', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان الربيع ابن خيثم لا يعطي السائل أقل من رغيف، ويقول إني لأستحي من ربي ﷿ أن أرى غدا في ميزاني نصف رغيف.', 'حلية الأولياء', 2, 116, '{}', false, 'published'),
  ('732633a0-5433-4642-aef1-4dbf3bf1d0bf', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان أبو مسلم الخولاني يكثر أن يرفع صوته بالتكبير حتى مع الصبيان، وكان يقول اذكروا الله حتى يرى الجاهل أنكم مجانين.', 'حلية الأولياء', 2, 124, '{}', false, 'published'),
  ('542ce1eb-7bce-4762-8fc6-2462925dffef', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان سعيد بن المسيب يماري غلاما له في ثلثي درهم وأتاه ابن عمه بأربعة آلاف درهم فأبى أن يأخذها.', 'حلية الأولياء', 2, 166, '{}', false, 'published'),
  ('833d6001-393b-4134-b405-c36e56eb6fb3', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان عروة بن الزبير إذا كان أيام الرطب يثلم حائطه ثم يأذن للناس فيه فيدخلون ويأكلون ويحملون.', 'حلية الأولياء', 2, 180, '{}', false, 'published'),
  ('6fbdb287-462b-44df-96fa-bb8802eee2e5', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان مطرف ابن عبد الله يبدو فاذا كان ليلة الجمعة ادلج على فرسه فربما نور له سوطه.', 'حلية الأولياء', 2, 205, '{}', false, 'published'),
  ('6a8572fb-38d7-485e-9576-1c80144968f1', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان أبو العالية إذا جلس إليه أكثر من أربعة قام.', 'حلية الأولياء', 2, 218, '{}', false, 'published'),
  ('7e971b35-096c-4a5f-9939-6c9a965476d7', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان محمد بن سيرين إذا سئل عن شيء من الفقه الحلال والحرام تغير لونه وتبدل، حتى كأنه ليس بالذي كان.', 'حلية الأولياء', 2, 264, '{}', false, 'published'),
  ('e3e7da3e-73dd-482f-9043-89a1f8859677', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان محمد بن سيرين يقول لا تكرم أخاك بما يشق عليك.', 'حلية الأولياء', 2, 264, '{}', false, 'published'),
  ('b2c9d540-265f-47ff-a4d9-46a1307a0575', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان محمد بن سيرين إذا ذكر الموت مات كل عضو منه على حدته.', 'حلية الأولياء', 2, 272, '{}', false, 'published'),
  ('7a69e63a-cc7b-4e8b-89ca-d270d02d4561', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان محمد بن سيرين يتمثل الشعر، ويذكر الشئ ويضحك، حتى إذا جاء الحديث من السنة كلح وانضم بعضه إلى بعض.', 'حلية الأولياء', 2, 274, '{}', false, 'published'),
  ('361b7e70-6baf-4640-b84e-f6eaccd8c03f', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان ابن سيرين يمازح أصحابه، ويقول مرحبا بالمدرفشين - يعني أنكم تشهدون الجنائز، وتحملون الموتى.', 'حلية الأولياء', 2, 274, '{}', false, 'published'),
  ('dfe9e1a7-0a97-446f-ba78-b3a084dfad38', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان محمد بن واسع إذا انتبه من منامه ضرب بيده إلى دبره.', 'حلية الأولياء', 2, 349, '{}', false, 'published'),
  ('d4a44e2d-2a37-4ceb-9005-706ce2b15968', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان محمد بن واسع يقول اللهم إن كان أخلق وجهي كثرة ذنوبي فهبني لمن أحببت من خلقك.', 'حلية الأولياء', 2, 353, '{}', false, 'published'),
  ('019260e7-cea2-4a74-89c9-17125489b7b2', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان مالك بن دينار يلبس إزار صوف وعباءة خفيفة فإذا كان الشتاء ففرو.', 'حلية الأولياء', 2, 368, '{}', false, 'published'),
  ('2e0d80ac-0ae9-4b28-8092-97b78b50cd0f', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان ابن عون يصوم يوما ويفطر يوما.', 'حلية الأولياء', 3, 40, '{}', false, 'published'),
  ('a946bb55-bf7e-4d24-9603-5add7e70cc40', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان الحسن يقعد مع أصحابه، فلا يقوم حتى يختم منصور بن زاذان القرآن.', 'حلية الأولياء', 3, 58, '{}', false, 'published'),
  ('1ed50513-55f2-4b12-b448-5f6e6db5015b', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان منصور بن زاذان يختم القرآن في كل يوم وليلة.', 'حلية الأولياء', 3, 58, '{}', false, 'published'),
  ('b856fef8-fd86-4662-9a4d-242df4ec7863', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان جابر بن زيد لا يماكس في كل شيء يتقرب به إلى الله ﷿.', 'حلية الأولياء', 3, 87, '{}', false, 'published'),
  ('2d6b67e4-a95e-413e-811d-1201f3b6e9c1', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان علي بن الحسين إذا فرغ من وضوئه للصلاة، وصار بين وضوئه وصلاته أخذته رعدة ونفضة.', 'حلية الأولياء', 3, 133, '{}', false, 'published'),
  ('e83e1d40-5730-45ad-addc-696b74c71294', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان علي بن الحسين لا يضرب بعيره من المدينة إلى مكة.', 'حلية الأولياء', 3, 133, '{}', false, 'published'),
  ('45b1d99e-4b51-424a-a6d4-e41c68c7317d', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان علي بن الحسين يبخل، فلما مات وجدوه يقوت مائة أهل بيت بالمدينة.', 'حلية الأولياء', 3, 136, '{}', false, 'published'),
  ('4260c7b9-5df9-4e06-810d-1b310b866d79', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان علي بن الحسين يتخطى حلق قومه حتى يأتي زيد بن أسلم فيجلس عنده.', 'حلية الأولياء', 3, 138, '{}', false, 'published'),
  ('1dafe5f5-7d5e-4879-b319-1602bd890a8a', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان سعد بن إبراهيم يصوم الدهر.', 'حلية الأولياء', 3, 169, '{}', false, 'published'),
  ('2e4f1352-92cd-4b6d-b744-996dcc608e05', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان جعفر بن محمد يطعم حتى لا يبقى لعياله شيء.', 'حلية الأولياء', 3, 194, '{}', false, 'published'),
  ('b619a8cc-6d0f-47e6-aad4-d17f39ea1f41', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان عمرو بن عتبة يصلي والسبع حوله يضرب بذنبه يحميه.', 'حلية الأولياء', 4, 157, '{}', false, 'published'),
  ('5bbb40c3-f0f2-4943-84a4-0da0229cffc9', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان عمرو بن عتبة يرعى ركاب أصحابه وغمامة تظله.', 'حلية الأولياء', 4, 157, '{}', false, 'published'),
  ('e99b6c0a-0506-4cc3-a1f8-d8d904b84d0e', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان سويد بن غفلة يؤمنا في شهر رمضان في القيام، وقد أتى عليه عشرون ومائة سنة.', 'حلية الأولياء', 4, 175, '{}', false, 'published'),
  ('39a32df5-7f57-4d06-9594-38cc63185ef0', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان سعيد بن جبير يبكي بالليل حتى عمش.', 'حلية الأولياء', 4, 272, '{}', false, 'published'),
  ('8c2e7889-3b96-4eec-a009-ebb1b7f7b1ff', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان سعيد بن جبير يؤمنا يرجع صوته بالقرآن.', 'حلية الأولياء', 4, 273, '{}', false, 'published'),
  ('1f197350-1423-468a-a88e-11608e3a82e2', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان سعيد بن جبير يختم القرآن فيما بين المغرب والعشاء في شهر رمضان.', 'حلية الأولياء', 4, 273, '{}', false, 'published'),
  ('a133c81e-f6fa-4925-9255-3ec5ab84707f', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان طلحة بن مصرف يقول في دعائه اللهم اغفر لى ريائى وسمعتي.', 'حلية الأولياء', 5, 16, '{}', false, 'published'),
  ('7e60a4c4-d33b-441b-9ad0-89f41a917915', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان عبد الرحمن بن أبي نعم يواصل خمسة عشر يوما لا يأكل ولا يشرب.', 'حلية الأولياء', 5, 69, '{}', false, 'published'),
  ('340fe6e5-a01b-4838-ab22-5fca31cef11c', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان ابن أبي نعم يحرم من السنة إلى السنة، وكان يقول فى تلبيته لبيك، لو كان رياء لاضمحل لبيك.', 'حلية الأولياء', 5, 70, '{}', false, 'published'),
  ('c03e79c3-3de7-434b-9e54-ad6beeb9807b', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان ابن أبي نعم يحرم من السنة إلى السنة، فآذاه القمل فدعا ربه ﷿، فوقعت كبة بين يديه.', 'حلية الأولياء', 5, 70, '{}', false, 'published'),
  ('52a42128-7ba3-4bb7-bbf2-641722c8cbf4', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'وكان محمد بن طارق يطوف في كل يوم وليلة سبعين أسبوعا؛ وكان كرز يختم القرآن في كل يوم وليلة ثلاث ختمات.', 'حلية الأولياء', 5, 81, '{}', false, 'published'),
  ('2ff34b75-63af-44e8-94d0-bfcf487111eb', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'وكان ابن ابجر يعالج من نفسه شدة شديدة، ولكن لا يتكلم بشيء.', 'حلية الأولياء', 5, 84, '{}', false, 'published'),
  ('0123dd13-e784-4c70-8fa0-6de4b1d730e6', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان عمرو بن قيس الملائي يقرئ الناس القرآن، فكان يجلس بين يدي رجل رجل حتى يفرغ منهم، وكان إذا مشى لا يمشي أمامهم فيقول تعالوا نمشي جميعا.', 'حلية الأولياء', 5, 102, '{}', false, 'published'),
  ('a640d273-56de-4071-948f-7c27ac2a58a3', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان عمرو بن قيس إذا بكى حول وجهه إلى الحائط، ويقول لأصحابه إن هذا زكام.', 'حلية الأولياء', 5, 103, '{}', false, 'published'),
  ('72bbe3d3-ce72-4ba9-8c82-f1f482a6c9ba', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان عبد الله بن زكريا إذا قدم فلسطين فرأى ابن محيريز صغرت إليه نفسه لما يرى من فضله.', 'حلية الأولياء', 5, 143, '{}', false, 'published'),
  ('7d4cd1c8-7f24-446c-a407-9622b8d78bd0', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان ابن محيريز يجئ إلى عبد الملك بصحيفة فيها النصيحة يقرئه ما فيها، فإذا فرغ منها أخذ الصحيفة.', 'حلية الأولياء', 5, 144, '{}', false, 'published'),
  ('ecf90ca0-5e81-474f-abf4-bdcc48465895', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان ابن محيريز إذا غزا كان أعجب النفقة إليه في علف الدواب.', 'حلية الأولياء', 5, 144, '{}', false, 'published'),
  ('e4d2d17c-9aae-4650-b1f0-8e400728d679', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان ابن عون إذا ذكر من يعجبه ذكر رجاء بن حيوة.', 'حلية الأولياء', 5, 170, '{}', false, 'published'),
  ('d85ddbd6-d9ce-431d-866e-171a2ba3445e', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان خالد ابن معدان يسبح في اليوم أربعين ألف تسبيحة، سوى ما يقرأ من القرآن، فلما مات ووضع على سريره ليغسل، جعل بإصبعه كذا يحركها - يعني بالتسبيح-.', 'حلية الأولياء', 5, 210, '{}', false, 'published'),
  ('3e3a0780-32a7-4f97-9e2d-d87aad495e98', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'وكان عمر بن عبد العزيز يجعل كل يوم درهما من خاصة ماله في طعام المسلمين ثم يأكل معهم.', 'حلية الأولياء', 5, 270, '{}', false, 'published'),
  ('f1767f33-99cb-496c-86e5-5f565f890276', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان عمر بن عبد العزيز يلبس الفرو الغليظ، وكان سراجه على ثلاث قصبات فوقهن طين.', 'حلية الأولياء', 5, 323, '{}', false, 'published'),
  ('10aa8d30-6f82-4812-b169-830c5e0b7eb2', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان عمر بن عبد العزيز يعلم العلماء.', 'حلية الأولياء', 5, 340, '{}', false, 'published'),
  ('c63d2ebf-b96f-483d-a40b-51c93a67bb2d', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان حسان بن عطية يتنحى إذا صلى العصر في ناحية المسجد فيذكر الله حتى تغيب الشمس.', 'حلية الأولياء', 6, 70, '{}', false, 'published'),
  ('041c02e3-c852-49ca-8cd7-7eb52b9a9408', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان الأوزاعي لا يكلم أحدا بعد صلاة الفجر حتى يذكر الله، فإن كلمه أحد أجابه.', 'حلية الأولياء', 6, 143, '{}', false, 'published'),
  ('0d8e4f77-f639-49d2-8321-1e3bd0cde55a', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'وكان بشر بن منصور يستحب أن يصلي بالأوقات ولا يتحرى.', 'حلية الأولياء', 6, 239, '{}', false, 'published'),
  ('2d5cc963-af9f-4b12-ac68-d524993ff6b0', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان ابن مسعود يقرأ القرآن من الجمعة إلى الجمعة ويقرأه في رمضان في ثلاث.', 'حلية الأولياء', 7, 166, '{}', false, 'published'),
  ('64c7decc-027d-45b0-ac82-78faa1f7a185', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان ابن السماك يقول في آخر كلامه ألا متأهب فيما يوصف له أمامه مستعد ليوم فقره وفاقته، ألا شاب عادم مبادر لمنيته ليس يغره شبابه ولا شدة قوته.', 'حلية الأولياء', 8, 210, '{}', false, 'published'),
  ('3ea92c29-33ed-4331-af4e-c8e6c4a58aa7', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان محمد بن النضر إذا ذكر الموت اضطربت مفاصله حتى تتبين الرعدة فيها.', 'حلية الأولياء', 8, 218, '{}', false, 'published'),
  ('927c55dc-7a68-4cb4-9bfc-32233188847a', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان عبد الرحمن يحج كل سنة، فمات أخوه وأوصى إليه وقبل وصيته، وقام على أيتامه وترك الحج.', 'حلية الأولياء', 9, 14, '{}', false, 'published'),
  ('8c959e0b-f7bd-47f3-989e-f74f4c1d78c9', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'وكان الشافعي يصنع كتابا من غدوة إلى الظهر من حفظه من غير أن يكون في يده أصل.', 'حلية الأولياء', 9, 129, '{}', false, 'published'),
  ('96c507e1-cbad-4c9c-9acf-89687efed0e9', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان الشافعي يختم القرآن ستين ختمة.', 'حلية الأولياء', 9, 134, '{}', false, 'published'),
  ('7562b237-fd5f-4785-aa3b-7177b9bebf81', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان أبو أمامة يحب الصدقة ويجمع لها، وما يرد سائلا ولو ببصلة أو بتمرة أو بشيء مما يؤكل.', 'حلية الأولياء', 10, 129, '{}', false, 'published'),
  ('a6ae4875-5637-43ac-95b5-0bbbd002b8b5', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000002', 'biography', 'كان زيد بن أخرم يسميه عابد أهل أصبهان.', 'حلية الأولياء', 10, 391, '{}', false, 'published'),
  ('fa6214a1-2c8c-4b43-b07a-0fb64fc67bbf', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان زيد بن الخطاب يحمل راية المسلمين يوم اليمامة وقد انكشف المسلمون حتى غلبت بنو حنيفة عن الرحال، فجعل زيد يقول أما الرحال فلا رحال، وأما الفرار فلا فرار.', 'صفة الصفوة', 1, 168, '{}', false, 'published'),
  ('df2e3446-b6a0-40b0-b1c2-bd8485a7a842', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان معاذ بن عفراء لا يدع شيئاً إلا تصدق به.', 'صفة الصفوة', 1, 178, '{}', false, 'published'),
  ('0d58e19d-ec67-4715-92a9-b926a454a98b', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان ابن عباس يقوم على منبرنا هذا فيقرأ البقرة وآل عمران فيفسرهما آية آية.', 'صفة الصفوة', 1, 295, '{}', false, 'published'),
  ('968d7cdc-5719-4bbf-9281-05d04063b90b', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان ابن الزبير، إذا قام في الصلاة، كأنه عود؛ من الخشوع.', 'صفة الصفوة', 1, 302, '{}', false, 'published'),
  ('6d0deef4-c2c8-4e14-b0de-ed6f98274080', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان عبد الله بن الزبير يحيي الدهر أجمع، ليلةً قائماً حتى يصبح، وليلةً يحييها راكعاً حتى الصباح، وليلةً يحييها ساجداً حتى الصباح.', 'صفة الصفوة', 1, 303, '{}', false, 'published'),
  ('17dc1bd5-b50e-44a3-91a1-67c1d8dbb28f', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان ابن الزبير يواصل سبعة أيام، ويصبح اليوم السابع وهو اليثا.', 'صفة الصفوة', 1, 303, '{}', false, 'published'),
  ('b15b5299-4100-4120-bd95-b05909efd2c8', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان سعيد بن المسيب يُسرُد الصومَ.', 'صفة الصفوة', 1, 346, '{}', false, 'published'),
  ('443b3254-5830-4911-b5e4-5e9b7d49e815', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان عروة بن الزبير إذا كان أيام الرطب ثلم حائطه فيدخل الناس فيأكلون ويحملون.', 'صفة الصفوة', 1, 349, '{}', false, 'published'),
  ('ff558f82-304b-40b6-80e4-764647f7ccb3', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان محمد بن علي يجيز بالخمسمائة والتسمائة إلى الألف، وكان (لا) يملّ من مجالسة إخوانه غنيّاً.', 'صفة الصفوة', 1, 364, '{}', false, 'published'),
  ('ec70c0b4-e190-4eee-b2ea-88d9ac5047f0', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان عبد الرحمن بن أبان يشتري أهل البيت ثم يأمر بهم فيكسون ويدهنون ثم يعرضون عليه فيقول انتم أحرار لوجه الله استعين بكم على غمرات الموت.', 'صفة الصفوة', 1, 382, '{}', false, 'published'),
  ('8d358bf4-450a-431b-b041-8802f87cda21', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'وكان ابن مهدي يقول ما نظرت إليه الا ذكرت به سفيان الثوري ولقد كاد هذا الغلام ان يكون إماما في بطن أمه.', 'صفة الصفوة', 1, 479, '{}', false, 'published'),
  ('2e5761b9-cba4-44a0-a0f3-3d8ac5c20d89', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'وكان الشبلي ينوح يوما ويقول مكر بك في احسانه فتناسيت وامهلك في غيك فتماديت واسقطك من عينه فما دريت ولا باليت.', 'صفة الصفوة', 1, 541, '{}', false, 'published'),
  ('b908516b-41d6-48a6-b36d-3f0988b49d2d', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'وكانت الضجة تمنع التبليغ للتكبير فصلى اكثر الناس وحدانا ورأيت عدة بنانيك فيها من المداسات الكثيرة ينادي عليها لياخذها اربابها.', 'صفة الصفوة', 1, 558, '{}', false, 'published'),
  ('4fad33bf-f4b1-4298-902e-0be8ab809d04', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان الحسن يقعد مع أصحابه ولا يقوم حتى يختم منصور بن زاذان القرآن.', 'صفة الصفوة', 2, 7, '{}', false, 'published'),
  ('391b0c9f-ef52-44cb-b345-48dbe873d939', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان الأسود يختم القرآن في رمضان في ليلتين، وكان ينام بين المغرب والعشاء، وكان يختم القرآن في غير رمضان، في كل ست ليال.', 'صفة الصفوة', 2, 14, '{}', false, 'published'),
  ('1ed7e32d-c8a1-44d5-8b22-4139dedb72fd', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان أبو وائل إذا خلا يسبح، ولو جعلت له الدنيا على أن يفعل ذلك وأحد يراه لم يفعل.', 'صفة الصفوة', 2, 17, '{}', false, 'published'),
  ('e6b30013-cce0-480d-8a30-3b6ad4b2cc6c', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان شقيق بن سلمة يدخل المسجد يصلي ثم ينشج كما تنشج المرأة.', 'صفة الصفوة', 2, 17, '{}', false, 'published'),
  ('b7c8ba7b-ca0a-482c-a5f4-fac20919fc05', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان عمرو بن ميمون إذا دخل المسجد فرئي ذكر الله عز وجل.', 'صفة الصفوة', 2, 21, '{}', false, 'published'),
  ('46fecab6-d320-49f3-95ed-6067e3d689d8', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'وكان الربيع إذا أتى عبد الله لم يكن عليه إذن حتى يفرغ كل واحد منهما من صاحبه.', 'صفة الصفوة', 2, 34, '{}', false, 'published'),
  ('2104e2a6-6ebc-43a2-808d-294fb9be8354', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان الربيع بن خثيم يقول السرائر التي تختفي على الناس وهي لله بواد، التمسوا دواءهن التمسوا دواءهن.', 'صفة الصفوة', 2, 35, '{}', false, 'published'),
  ('98965866-ec7e-40c1-8cc8-81e5b15cae1a', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان الربيع ابن خثيم إذا سجد كأنه ثوب مطروح فتجيء العصافير فتقع عليه.', 'صفة الصفوة', 2, 36, '{}', false, 'published'),
  ('8111c14f-d10f-478f-a8e8-7b54ab517709', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان عمرو بن عتبة يصلي والحمام فوق رأسه، والسباع حوله، تحرك أذنابها.', 'صفة الصفوة', 2, 40, '{}', false, 'published'),
  ('97c4c917-a5ab-4671-b17a-4b004d9e5b1a', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان سعيد بن جبير إذا قام إلى الصلاة كأنه وتد.', 'صفة الصفوة', 2, 44, '{}', false, 'published'),
  ('c8a605ac-2195-414c-b488-e8911f403cc5', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان أبو إسحاق يقوم ليل الصيف كله، وأما الشتاء فأوله وآخره، وبين ذلك هجعة.', 'صفة الصفوة', 2, 60, '{}', false, 'published'),
  ('322ac754-e3a1-4a02-ad50-cd2ba4258048', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'فكانت المسئلة تجيء وأنا أشد شهوة للجواب فيها من العطشان إلى الماء فلا أجيب فيها.', 'صفة الصفوة', 2, 76, '{}', false, 'published'),
  ('39d185f7-efdf-49e2-8947-74c28fcc017d', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان الحسن بن حي إذا أراد أن يعظ أخا له كتبه في لوح وناوله.', 'صفة الصفوة', 2, 88, '{}', false, 'published'),
  ('98c6e86b-961c-43e5-9ced-375af2352cb0', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان حسن بن صالح إذا صعد إلى المنارة أشرف على المقابر فإذا نظر إلى الشمس تحوم على القبور صرخ حتى يحمل مغشياً عليه فينزل به.', 'صفة الصفوة', 2, 89, '{}', false, 'published'),
  ('df832b16-4100-40ee-a6db-b0f208444789', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان أبو بكر بن عياش يقوم الليل في قباء صوف وسراويل وعكازة يضعها في صدره فيتكئ عليها حين كبر فيحيي ليلته.', 'صفة الصفوة', 2, 95, '{}', false, 'published'),
  ('4f6a75a4-3238-4ccc-9b8b-e9a75b444a82', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان حجير بن الربيع يصلي حتى ما يأتي فراشه إلا زحفاً، وما يعدونه من أعبدهم.', 'صفة الصفوة', 2, 119, '{}', false, 'published'),
  ('d1397d39-17c3-4105-af16-5d829e80d686', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان أبو العالية إذا جلس غليه أكثر من أربعة قام.', 'صفة الصفوة', 2, 124, '{}', false, 'published'),
  ('b6a000cd-4583-4855-a0ea-860f05a607e6', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان صلة بن أشيم يخرج إلى الجبان فيتعبد فيها فكان يمر عليه شباب يلهون ويلعبون.', 'صفة الصفوة', 2, 127, '{}', false, 'published'),
  ('7086b19d-6e33-4597-bc79-ca5a2659e54c', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان أبو الصهباء يصلي حتى ما يستطيع أن يأتي فراشه إلا زحفاً.', 'صفة الصفوة', 2, 128, '{}', false, 'published'),
  ('797f8582-a1a7-4a8d-b6db-a3044c9060eb', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان مطرف بن عبد الله إذا دخل بيته سبحت معه آنية بيته.', 'صفة الصفوة', 2, 131, '{}', false, 'published'),
  ('aa39b9a3-d5fb-45fd-9318-c7a0d57e743e', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان محمد بن سيرين إذا حدث كأنه يتقي شيئاً، كأنه يحذر شيئاً.', 'صفة الصفوة', 2, 143, '{}', false, 'published'),
  ('774475ee-849a-4e66-b1c6-fb0422cb6d4d', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'وكان اليوم الذي يفطر فيه يتغدى ولا يتعشى، ثم يتسحر ويصبح صائماً.', 'صفة الصفوة', 2, 144, '{}', false, 'published'),
  ('5578f6f5-489d-412a-9724-c597c54950ee', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان ابن سيرين يصوم يوماً ويفطر يوماً.', 'صفة الصفوة', 2, 144, '{}', false, 'published'),
  ('3617bfa9-e64e-49eb-acb6-4e8619c7f883', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان ابن سيرين يحيي الليل في رمضان.', 'صفة الصفوة', 2, 146, '{}', false, 'published'),
  ('0772edaa-af6e-487e-ad15-0c36f4de968d', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان ابن سيرين إذا ذكر الموت مات كل عضو منه على حدته.', 'صفة الصفوة', 2, 146, '{}', false, 'published'),
  ('32948820-929c-4b95-9e42-f07fca42270f', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان أبو الجوزاء يواصل في الصوم بين سبعة أيام ثم يقبض على ذراع الشاب فيكاد يحطمها.', 'صفة الصفوة', 2, 152, '{}', false, 'published'),
  ('cc4d58ec-d371-4353-9e42-09cdb5ce091b', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان أبو عمران الجوني إذا سمع الأذان تغير لونه وفاضت عيناه.', 'صفة الصفوة', 2, 157, '{}', false, 'published'),
  ('d4e3b71b-3ec8-4fa9-88e1-e3552270d49b', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'وكان النساك يومئذ يشمرون ثيابهم وكان أيوب لا يفعل.', 'صفة الصفوة', 2, 173, '{}', false, 'published'),
  ('959ea230-c0f3-44ca-b036-cfec10762ff0', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان عبد العزيز بن سلمان إذا ذكر القيامة والموت صرخ كما تصرخ الثكلى ويصرخ الخائفون من جوانب المسجد.', 'صفة الصفوة', 2, 223, '{}', false, 'published'),
  ('ba70800a-a40e-4ed7-b6ab-740e1d772479', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان عبد الرحمن بن مهدي يختم في كل ليلتين، وكان ورده في كل ليلة نصف القرآن.', 'صفة الصفوة', 2, 227, '{}', false, 'published'),
  ('6cd03667-6bb2-41b7-a5bf-c1d6923609f0', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان أبو الحسن المكي يسف الخوص وكان لا يملك إلا داراً فلما ضعف عن سف الخوص باعها على شرط أن يكريه المشتري إياها وأودع الثمن عند المشتري، وكان يأخذ منه في كل شهر خمسة دراهم لنفقته ويعطي المشتري أجرة الدار.', 'صفة الصفوة', 2, 232, '{}', false, 'published'),
  ('c4f15c42-8bbb-4ea8-9393-7faee0fcde85', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كانت حفصة بنت سيرين تسرج سراجها من الليل ثم تقوم في مصلاها فربما طفئ السراج فيضيء لها البيت حتى تصبح.', 'صفة الصفوة', 2, 243, '{}', false, 'published'),
  ('c2d0d14e-9028-47d7-9939-4c9567a2e97e', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كانت أم حيان تقرأ القرآن في كل يوم وليلة، وكانت لا تتكلم إلا بعد العصر فإنها تأمر بالحاجة والشيء تريده.', 'صفة الصفوة', 2, 251, '{}', false, 'published'),
  ('44554d43-1e22-40ae-92a8-69eec192f1be', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'وكان أحمد بن حنبل يشبه بوكيع، وكان أبو داود يشبه بأحمد بن حنبل -رضي الله عنهم.', 'صفة الصفوة', 2, 276, '{}', false, 'published'),
  ('ee9e33fa-0296-48f6-a9ff-bbc93fb57d29', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان المعلى بن منصور الرازي يوماً يصلي فوقع على رأسه كور الزنابير فما التفت ولا انفتل حتى أتم صلاته فنظروا فإذا رأسه قد صار هكذا من شدة الانتفاخ.', 'صفة الصفوة', 2, 289, '{}', false, 'published'),
  ('e25384ed-02ca-4300-b1b8-2f2456cead52', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كانت أم ابن المبارك تركية، وكان الشبه لهم بيناً فيه، وكان ربما خلع قميصه فلا أرى على صدره وجسده كثير شعر.', 'صفة الصفوة', 2, 323, '{}', false, 'published'),
  ('1edfa8d3-3f8b-49e9-a67a-bd998de2658a', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'وكان عبد الله بن منير إذا قام من المجلس يخرج إلى البرية مع قوم مع أصحابه يجمع شيئاً مثل الأشنان وغيره فيدخل السوق فيبيع ذلك فيتعيش به.', 'صفة الصفوة', 2, 332, '{}', false, 'published'),
  ('dfcc4840-271e-41a0-a99f-37c29c506394', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان ابن محيريز يجيء بالكتاب إلى عبد الملك فيه النصيحة فيقرئه إياه ثم لا يقره في يده.', 'صفة الصفوة', 2, 368, '{}', false, 'published'),
  ('40942cd5-2074-470a-b83e-366b49d19a53', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان ابن زكريا يقدم فلسطين فيلقى ابن محيريز فتتقاصر إليه نفسه لما يرى من فضل ابن محيريز.', 'صفة الصفوة', 2, 369, '{}', false, 'published'),
  ('1477acbb-3d91-41b8-9441-1f000d0230ba', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان خالد بن معدان إذا عظمت حلقته قام فانصرف.', 'صفة الصفوة', 2, 374, '{}', false, 'published'),
  ('6297c6cc-e4cb-40c8-8528-fe315c558af8', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان عبد الله بن أبي زكريا إذا خاض جلساؤه في غير ذكر الله كأنه ساه، وإذا خاضوا في ذكر الله كان من أحسن الناس استماعاً.', 'صفة الصفوة', 2, 375, '{}', false, 'published'),
  ('fc4a49d1-6eee-4b51-b5e3-2a30fbfa3096', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كانت أم البنين تعتق في كل جمعة رقبة، وتحمل على فرس في سبيل الله عز وجل.', 'صفة الصفوة', 2, 431, '{}', false, 'published'),
  ('0bafc195-45ce-4a63-b505-454856df1043', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان أبو أمامة يحب الصدقة ويجمع لها، ولا يرد سائلاً ولو ببيضة، ولو بتمرة أو بشيء مما يؤكل، فأتاه سائل ذات يوم وقد أقفر من ذلك كله وما عنده إلا ثلاثة دنانير.', 'صفة الصفوة', 2, 436, '{}', false, 'published')
insert into public.hadiths (id, collection, text, narrator, chapter, number, volume, page, source_id, topic, tags, needs_reference_check, status) values
  ('44444444-4444-4444-8444-000000000001', 'bukhari', 'إِنَّمَا الْأَعْمَالُ بِالنِّيَّاتِ، وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى، فَمَنْ كَانَتْ هِجْرَتُهُ إِلَى دُنْيَا يُصِيبُهَا، أَوْ إِلَى امْرَأَةٍ يَنْكِحُهَا، فَهِجْرَتُهُ إِلَى مَا هَاجَرَ إِلَيْهِ.', 'عمر بن الخطاب رضي الله عنه', 'كتاب بدء الوحي', 1, 1, 6, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', array['النية', 'الإخلاص']::text[], false, 'published'),
  ('44444444-4444-4444-8444-000000000002', 'bukhari', 'من صام رمضان إيماناً واحتساباً، غُفر له ما تقدّم من ذنبه.', 'أبي هريرة رضي الله عنه', 'كتاب الإيمان', 38, 3, 45, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', array['الصيام', 'رمضان']::text[], false, 'published'),
  ('44444444-4444-4444-8444-000000000003', 'bukhari', 'من قام ليلة القدر إيماناً واحتساباً، غُفر له ما تقدّم من ذنبه.', 'أبي هريرة رضي الله عنه', 'كتاب صلاة التراويح', 1901, 3, 26, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', array['قيام الليل', 'ليلة القدر']::text[], false, 'published'),
  ('44444444-4444-4444-8444-000000000004', 'bukhari', 'من صلّى البَرْدَين دخل الجنة.', 'أبي موسى الأشعري رضي الله عنه', 'كتاب مواقيت الصلاة', 574, 1, 119, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', array['الصلاة']::text[], false, 'published'),
  ('44444444-4444-4444-8444-000000000005', 'muslim', 'الصلوات الخمس، والجمعة إلى الجمعة، ورمضان إلى رمضان، مكفّراتٌ ما بينهن إذا اجتُنبت الكبائر.', 'أبي هريرة رضي الله عنه', 'كتاب الطهارة', 233, 1, 209, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', array['الصلاة', 'التكفير']::text[], false, 'published'),
  ('44444444-4444-4444-8444-000000000006', 'muslim', 'مَنْ بَنَى مَسْجِدًا لِلَّهِ بَنَى اللَّهُ لَهُ فِي الْجَنَّةِ مِثْلَهُ.', 'عثمان بن عفان رضي الله عنه', 'كتاب المساجد ومواضع الصلاة', 533, 1, 378, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', array['الصدقة', 'المساجد']::text[], false, 'published'),
  ('44444444-4444-4444-8444-000000000007', 'bukhari', 'من قال: سبحان الله وبحمده، في يومٍ مائة مرة، حُطّت خطاياه وإن كانت مثل زَبَد البحر.', 'أبي هريرة رضي الله عنه', 'كتاب الدعوات', 6405, 8, 86, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', array['الذكر']::text[], false, 'published'),
  ('44444444-4444-4444-8444-000000000008', 'bukhari', 'كلمتان خفيفتان على اللسان، ثقيلتان في الميزان، حبيبتان إلى الرحمن: سبحان الله وبحمده، سبحان الله العظيم.', 'أبي هريرة رضي الله عنه', 'كتاب التوحيد', 7563, 8, 139, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', array['الذكر']::text[], false, 'published'),
  ('44444444-4444-4444-8444-000000000009', 'bukhari', 'مَنْ غَدَا إِلَى الْمَسْجِدِ وَرَاحَ، أَعَدَّ اللهُ لَهُ نُزُلَهُ مِنَ الْجَنَّةِ، كُلَّمَا غَدَا أَوْ رَاحَ.', 'أبي هريرة رضي الله عنه', 'كتاب الأذان', 662, 1, 133, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', array['الصلاة', 'المساجد']::text[], false, 'published'),
  ('44444444-4444-4444-8444-000000000010', 'bukhari', 'الساعي على الأرملة والمسكين كالمجاهد في سبيل الله.', 'أبي هريرة رضي الله عنه', 'كتاب النفقات', 5353, 8, 9, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', array['الصدقة', 'الإحسان']::text[], false, 'published'),
  ('44444444-4444-4444-8444-000000000011', 'muslim', 'من دلّ على خيرٍ فله مثل أجر فاعله.', 'أبي مسعود الأنصاري رضي الله عنه', 'كتاب الإمارة', 1893, 3, 1303, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', array['الدعوة', 'الإحسان']::text[], false, 'published'),
  ('44444444-4444-4444-8444-000000000012', 'muslim', 'أَحَبُّ الأَعْمَالِ إِلَى اللَّهِ تَعَالَى أَدْوَمُهَا وَإِنْ قَلَّ.', 'عائشة رضي الله عنها', 'كتاب صلاة المسافرين وقصرها', 783, 1, 541, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', array['المداومة']::text[], false, 'published'),
  ('44444444-4444-4444-8444-000000000013', 'muslim', 'من صلّى الصبح فهو في ذمة الله.', 'جندب بن عبد الله رضي الله عنه', 'كتاب المساجد ومواضع الصلاة', 657, 1, 454, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', array['الصلاة']::text[], false, 'published'),
  ('44444444-4444-4444-8444-000000000014', 'bukhari', 'من حجّ فلم يرفُث ولم يفسُق، رجع كيوم ولدته أمه.', 'أبي هريرة رضي الله عنه', 'كتاب الحج', 1521, 2, 133, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', array['الحج']::text[], false, 'published'),
  ('44444444-4444-4444-8444-000000000015', 'bukhari', 'أفضل الصدقة أن تصدّق وأنت صحيحٌ شحيح، تخشى الفقر وتأمُل الغنى.', 'أبي هريرة رضي الله عنه', 'كتاب الزكاة', 1419, 2, 110, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', array['الصدقة']::text[], false, 'published'),
  ('44444444-4444-4444-8444-000000000016', 'muslim', 'ركعتا الفجر خيرٌ من الدنيا وما فيها.', 'عائشة رضي الله عنها', 'كتاب صلاة المسافرين', 725, 1, 501, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', array['السنن الرواتب']::text[], false, 'published'),
  ('44444444-4444-4444-8444-000000000017', 'muslim', 'من سلك طريقاً يلتمس فيه علماً، سهّل الله له به طريقاً إلى الجنة.', 'أبي هريرة رضي الله عنه', 'كتاب الذكر والدعاء', 2699, 4, 2074, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', array['العلم']::text[], false, 'published'),
  ('44444444-4444-4444-8444-000000000018', 'muslim', 'الطُّهور شطر الإيمان، والحمد لله تملأ الميزان، وسبحان الله والحمد لله تملآن ما بين السماوات والأرض.', 'أبي مالك الأشعري رضي الله عنه', 'كتاب الطهارة', 223, 1, 203, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', array['الطهارة', 'الذكر']::text[], false, 'published'),
  ('44444444-4444-4444-8444-000000000019', 'bukhari', 'مَنْ شَهِدَ الجَنَازَةَ حَتَّى يُصَلِّيَ فَلَهُ قِيرَاطٌ، وَمَنْ شَهِدَ حَتَّى تُدْفَنَ كَانَ لَهُ قِيرَاطَانِ. قِيلَ: وَمَا الْقِيرَاطَانِ؟ قَالَ: مِثْلُ الْجَبَلَيْنِ الْعَظِيمَيْنِ.', 'أبي هريرة رضي الله عنه', 'كتاب الجنائز', 1325, 2, 87, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', array['الجنائز']::text[], false, 'published'),
  ('44444444-4444-4444-8444-000000000020', 'muslim', 'مَنْ صَلَّى اثْنَتَيْ عَشْرَةَ رَكْعَةً فِي يَوْمٍ وَلَيْلَةٍ، بُنِيَ لَهُ بِهِنَّ بَيْتٌ فِي الْجَنَّةِ.', 'أم حبيبة رضي الله عنها', 'كتاب صلاة المسافرين', 728, 1, 502, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', array['السنن الرواتب']::text[], false, 'published'),
  ('e383b7a5-90a0-40e5-9658-8baf124ed9c9', 'bukhari', 'إِذَا قَالَ أَحَدُكُمْ آمِينَ، وَقَالَتِ الْمَلَائِكَةُ فِي السَّمَاءِ آمِينَ، فَوَافَقَتْ إِحْدَاهُمَا الْأُخْرَى، غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ.', 'أبي هريرة رضي الله عنه', 'كتاب الأذان', 781, 1, 156, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', '{}', false, 'published'),
  ('0693dbc9-1694-45ec-9858-7e388b834bde', 'bukhari', 'بَيْنَا أَنَا نَائِمٌ، أُتِيتُ بِقَدَحِ لَبَنٍ، فَشَرِبْتُ حَتَّى أَنِّي لَأَرَى الرِّيَّ يَخْرُجُ فِي أَظْفَارِي، ثُمَّ أَعْطَيْتُ فَضْلِي عُمَرَ بْنَ الْخَطَّابِ. قَالُوا: فَمَا أَوَّلْتَهُ يَا رَسُولَ اللهِ؟ قَالَ: الْعِلْمَ.', 'ابن عمر رضي الله عنه', 'كتاب العلم', 82, 1, 27, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', '{}', false, 'published'),
  ('6f122b0f-1f53-4d74-886b-f5d874faaf49', 'bukhari', 'أَرَأَيْتُمْ لَوْ أَنَّ نَهَرًا بِبَابِ أَحَدِكُمْ، يَغْتَسِلُ فِيهِ كُلَّ يَوْمٍ خَمْسًا، مَا تَقُولُ: ذَلِكَ يُبْقِي مِنْ دَرَنِهِ. قَالُوا: لَا يُبْقِي مِنْ دَرَنِهِ شَيْئًا، قَالَ: فَذَلِكَ مِثْلُ الصَّلَوَاتِ الْخَمْسِ، يَمْحُو اللهُ بِهِ الْخَطَايَا.', null, 'كتاب مواقيت الصلاة', 528, 1, 112, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', '{}', false, 'published'),
  ('dd2b0c41-6270-4f45-96af-fdc5e784dcce', 'bukhari', 'يَتَعَاقَبُونَ فِيكُمْ مَلَائِكَةٌ بِاللَّيْلِ وَمَلَائِكَةٌ بِالنَّهَارِ، وَيَجْتَمِعُونَ فِي صَلَاةِ الْفَجْرِ وَصَلَاةِ الْعَصْرِ، ثُمَّ يَعْرُجُ الَّذِينَ بَاتُوا فِيكُمْ، فَيَسْأَلُهُمْ وَهُوَ أَعْلَمُ بِهِمْ: كَيْفَ تَرَكْتُمْ عِبَادِي؟ فَيَقُولُونَ: تَرَكْنَاهُمْ وَهُمْ يُصَلُّونَ، وَأَتَيْنَاهُمْ وَهُمْ يُصَلُّونَ.', 'أبي هريرة رضي الله عنه', 'كتاب مواقيت الصلاة', 555, 1, 115, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', '{}', false, 'published'),
  ('f8fb1845-5ff8-41e8-9053-4d7ff186fe7e', 'bukhari', 'أَنَا وَكَافِلُ الْيَتِيمِ فِي الْجَنَّةِ هَكَذَا وَقَالَ بِإِصْبَعَيْهِ السَّبَّابَةِ وَالْوُسْطَى.', 'سهل بن سعد رضي الله عنه', 'كتاب الأدب', 6005, 8, 9, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', '{}', false, 'published'),
  ('7da316cd-21a7-4eba-909e-4a4bcb88b456', 'bukhari', 'مَنْ قَامَ رَمَضَانَ إِيمَانًا وَاحْتِسَابًا، غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ، قَالَ ابْنُ شِهَابٍ: فَتُوُفِّيَ رَسُولُ اللهِ وَالْأَمْرُ عَلَى ذَلِكَ، ثُمَّ كَانَ الْأَمْرُ عَلَى ذَلِكَ فِي خِلَافَةِ أَبِي بَكْرٍ، وَصَدْرًا مِنْ خِلَافَةِ عُمَرَ.', 'أبي هريرة رضي الله عنه', 'كتاب صلاة التراويح', 2009, 3, 44, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', '{}', false, 'published'),
  ('a5da9092-7b64-4e4d-98b0-c648738a8a34', 'bukhari', 'مَنْ صَامَ يَوْمًا فِي سَبِيلِ اللهِ بَعَّدَ اللهُ وَجْهَهُ عَنِ النَّارِ سَبْعِينَ خَرِيفًا.', 'أبي سعيد رضي الله عنه', 'كتاب الجهاد والسير', 2840, 4, 26, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', '{}', false, 'published'),
  ('f2023bde-fabc-4e53-833a-69bbe7b475db', 'bukhari', 'مَنْ أَنْفَقَ زَوْجَيْنِ فِي سَبِيلِ اللهِ دَعَاهُ خَزَنَةُ الْجَنَّةِ كُلُّ خَزَنَةِ بَابٍ: أَيْ فُلُْ هَلُمَّ. قَالَ أَبُو بَكْرٍ: يَا رَسُولَ اللهِ ذَاكَ الَّذِي لَا تَوَى عَلَيْهِ فَقَالَ النَّبِيُّ: إِنِّي لَأَرْجُو أَنْ تَكُونَ مِنْهُمْ.', 'أبي هريرة رضي الله عنه', 'كتاب الجهاد والسير', 2841, 4, 26, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', '{}', false, 'published'),
  ('831d196a-52a9-4579-9324-da789286d7cc', 'bukhari', 'مَنْ جَهَّزَ غَازِيًا فِي سَبِيلِ اللهِ فَقَدْ غَزَا وَمَنْ خَلَفَ غَازِيًا فِي سَبِيلِ اللهِ بِخَيْرٍ فَقَدْ غَزَا.', 'زيد بن خالد رضي الله عنه', 'كتاب الجهاد والسير', 2843, 4, 27, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', '{}', false, 'published'),
  ('2644cbae-b083-478b-8a60-e21c6e435772', 'bukhari', 'إِذَا قَالَ الْإِمَامُ: سَمِعَ اللهُ لِمَنْ حَمِدَهُ، فَقُولُوا: اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ، فَإِنَّهُ مَنْ وَافَقَ قَوْلُهُ قَوْلَ الْمَلَائِكَةِ، غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ.', 'أبي هريرة رضي الله عنه', 'كتاب الأذان', 796, 1, 158, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', '{}', false, 'published'),
  ('0d917609-8562-4f74-b3ca-84f3b92a7e7e', 'bukhari', 'مَا بَيْنَ بَيْتِي وَمِنْبَرِي رَوْضَةٌ مِنْ رِيَاضِ الْجَنَّةِ.', 'عبد الله بن زيد المازني رضي الله عنه', 'كتاب فضل الصلاة في مسجد مكة والمدينة', 1195, 2, 61, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', '{}', false, 'published')
insert into public.duas (id, text, narrator, collection, number, volume, page, source_id, source_url, tags, needs_reference_check, sort_order, status) values
  ('b8d7159a-388d-4cb9-96f7-2efd7081db60', 'اللَّهُمَّ رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً، وَفِي الآخِرَةِ حَسَنَةً، وَقِنَا عَذَابَ النَّارِ', 'أنس رضي الله عنه', 'صحيح البخاري', 6389, 8, 83, '33333333-3333-4333-8333-000000000001', 'https://app.turath.io/book/1681/9587', '{}', false, 1, 'published'),
  ('5d706ef1-1bdb-4e3d-9612-51f0c1b581b8', 'لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ', 'سعد بن أبي وقاص رضي الله عنه', 'صحيح الترغيب', 1644, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 2, 'published'),
  ('198f9065-afe5-4701-aff7-deca997894f7', 'اللَّهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَعَافِنِي، وَارْزُقْنِي', 'أبو مالك الأشجعي رضي الله عنه', 'صحيح مسلم', 2697, 4, 2073, '33333333-3333-4333-8333-000000000001', 'https://app.turath.io/book/1727/6785', '{}', false, 3, 'published'),
  ('4bee7ca5-6e27-4f5e-afdf-d29cbd01b599', 'اللَّهُمَّ أَعِنَّا عَلَى شُكْرِكَ، وَذِكْرِكَ، وَحُسْنِ عِبَادَتِكَ', 'أبو هريرة رضي الله عنه', 'السلسلة الصحيحة', 844, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 4, 'published'),
  ('43b19d87-657b-43a2-9a2d-153c8d6065eb', 'اللَّهُمَّ إِنِّي أَسْأَلُكَ المُعَافَاةَ فِي الدُّنْيَا وَالآخِرَةِ', 'أبو هريرة رضي الله عنه', 'صحيح الجامع', 5703, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 5, 'published'),
  ('abd4deaf-882c-4237-8fd0-d65d0dd76f4e', 'اللَّهُمَّ أَصْلِحْ لِي دِينِي الَّذِي هُوَ عِصْمَةُ أَمْرِي، وَأَصْلِحْ لِي دُنْيَايَ الَّتِي فِيهَا مَعَاشِي، وَأَصْلِحْ لِي آخِرَتِي الَّتِي فِيهَا مَعَادِي، وَاجْعَلِ الحَيَاةَ زِيَادَةً لِي فِي كُلِّ خَيْرٍ، وَاجْعَلِ المَوْتَ رَاحَةً لِي مِنْ كُلِّ شَرٍّ', 'أبو هريرة رضي الله عنه', 'صحيح مسلم', 2720, 4, 2087, '33333333-3333-4333-8333-000000000001', 'https://app.turath.io/book/1727/6837', '{}', false, 6, 'published'),
  ('95514938-22a1-4617-96ef-620404f5f6b6', 'اللَّهُمَّ إِنِّي أَسْأَلُكَ الهُدَى، وَالتُّقَى، وَالعَفَافَ، وَالغِنَى', 'عبد الله بن مسعود رضي الله عنه', 'صحيح مسلم', 2721, 4, 2087, '33333333-3333-4333-8333-000000000001', 'https://app.turath.io/book/1727/6838', '{}', false, 7, 'published'),
  ('126c0a93-1bd5-46bc-a9d8-f3b6f0a53391', 'يَا مُقَلِّبَ القُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ', 'أم سلمة رضي الله عنه', 'السلسلة الصحيحة', 2091, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 8, 'published'),
  ('87ea05a1-8a37-4783-959c-b50338ffe020', 'اللَّهُمَّ مُصَرِّفَ القُلُوبِ صَرِّفْ قُلُوبَنَا عَلَى طَاعَتِكَ', 'عبد الله بن عمرو رضي الله عنه', 'صحيح مسلم', 2654, 4, 2045, '33333333-3333-4333-8333-000000000001', 'https://app.turath.io/book/1727/6685', '{}', false, 9, 'published'),
  ('628f4b71-2bf9-4481-ba2d-325569b8163c', 'اللَّهُمَّ اهْدِنِي وَسَدِّدْنِي', 'علي رضي الله عنه', 'صحيح مسلم', 2725, 4, 2090, '33333333-3333-4333-8333-000000000001', 'https://app.turath.io/book/1727/6845', '{}', false, 10, 'published'),
  ('dd0ac2ec-3995-4c2c-a15d-172a84bb712b', 'اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ العَفْوَ فَاعْفُ عَنِّي', 'عائشة رضي الله عنه', 'صحيح ابن ماجه', 3119, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 11, 'published'),
  ('be8626d2-5091-49bd-89fa-cd94d405f192', 'اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ وَرَحْمَتِكَ، فَإِنَّهُ لَا يَمْلِكُهَا إِلَّا أَنْتَ', 'عبد الله بن مسعود رضي الله عنه', 'السلسلة الصحيحة', 1543, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 12, 'published'),
  ('fb3ef276-5f80-403c-a0cb-72cc8c6f6c36', 'اللَّهُمَّ اكْفِنِي بِحَلَالِكَ عَنْ حَرَامِكَ، وَأَغْنِنِي بِفَضْلِكَ عَمَّنْ سِوَاكَ', 'علي رضي الله عنه', 'صحيح الجامع', 2625, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 13, 'published'),
  ('d2a9fee2-a22f-4db9-b605-264e75313b2b', 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ مُنْكَرَاتِ الأَخْلَاقِ وَالأَعْمَالِ وَالأَهْوَاءِ', 'قطبة بن مالك رضي الله عنه', 'صحيح الترمذي', 3591, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 14, 'published'),
  ('af12b4ca-25e4-4c37-a519-41197e5a9c9a', 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ البَرَصِ وَالجُنُونِ وَالجُذَامِ، وَمِنْ سَيِّئِ الأَسْقَامِ', 'أنس بن مالك رضي الله عنه', 'صحيح الجامع', 1281, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 15, 'published'),
  ('d4857131-67e5-4052-be26-41b165821da2', 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ جَارِ السُّوءِ فِي دَارِ المُقَامَةِ، فَإِنَّ جَارَ البَادِيَةِ يَتَحَوَّلُ', 'أبو هريرة رضي الله عنه', 'صحيح الجامع', 1290, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 16, 'published'),
  ('2905c606-1931-4e86-bd8c-53a7e353aade', 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ القِلَّةِ وَالفَقْرِ وَالذِّلَّةِ، وَأَعُوذُ بِكَ أَنْ أَظْلِمَ أَوْ أُظْلَمَ', 'أبو هريرة رضي الله عنه', 'صحيح النسائي', 5477, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 17, 'published'),
  ('2ba8926e-d7a3-48d2-b411-7e75f85217bf', 'اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنَ الخَيْرِ كُلِّهِ عَاجِلِهِ وَآجِلِهِ مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ، وَأَعُوذُ بِكَ مِنَ الشَّرِّ كُلِّهِ عَاجِلِهِ وَآجِلِهِ مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ، اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ خَيْرِ مَا سَأَلَكَ مِنْهُ عَبْدُكَ وَنَبِيُّكَ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا عَاذَ بِهِ عَبْدُكَ وَنَبِيُّكَ، اللَّهُمَّ إِنِّي أَسْأَلُكَ الجَنَّةَ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ، وَأَعُوذُ بِكَ مِنَ النَّارِ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ، وَأَسْأَلُكَ أَنْ تَجْعَلَ كُلَّ قَضَاءٍ قَضَيْتَهُ لِي خَيْرًا', 'عائشة رضي الله عنه', 'السلسلة الصحيحة', 1542, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 18, 'published'),
  ('b2af4508-aae9-497e-808e-69d87c921915', 'اللَّهُمَّ إِنِّي أَسْأَلُكَ الثَّبَاتَ فِي الأَمْرِ، وَالعَزِيمَةَ عَلَى الرُّشْدِ، وَأَسْأَلُكَ مُوجِبَاتِ رَحْمَتِكَ، وَعَزَائِمَ مَغْفِرَتِكَ، وَأَسْأَلُكَ شُكْرَ نِعْمَتِكَ، وَحُسْنَ عِبَادَتِكَ، وَأَسْأَلُكَ قَلْبًا سَلِيمًا، وَلِسَانًا صَادِقًا، وَأَسْأَلُكَ مِنْ خَيْرِ مَا تَعْلَمُ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا تَعْلَمُ، وَأَسْتَغْفِرُكَ لِمَا تَعْلَمُ؛ إِنَّكَ أَنْتَ عَلَّامُ الغُيُوبِ', 'شداد بن أوس رضي الله عنه', 'السلسلة الصحيحة', 3228, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 19, 'published'),
  ('655be48a-241d-4337-942f-47a639b7bb4b', 'اللَّهُمَّ اقْسِمْ لَنَا مِنْ خَشْيَتِكَ مَا يَحُولُ بَيْنَنَا وَبَيْنَ مَعَاصِيكَ، وَمِنْ طَاعَتِكَ مَا تُبَلِّغُنَا بِهِ جَنَّتَكَ، وَمِنَ اليَقِينِ مَا تُهَوِّنُ بِهِ عَلَيْنَا مُصِيبَاتِ الدُّنْيَا، وَمَتِّعْنَا بِأَسْمَاعِنَا وَأَبْصَارِنَا وَقُوَّتِنَا مَا أَحْيَيْتَنَا، وَاجْعَلْهُ الوَارِثَ مِنَّا، وَاجْعَلْ ثَأْرَنَا عَلَى مَنْ ظَلَمَنَا، وَانْصُرْنَا عَلَى مَنْ عَادَانَا، وَلَا تَجْعَلْ مُصِيبَتَنَا فِي دِينِنَا، وَلَا تَجْعَلِ الدُّنْيَا أَكْبَرَ هَمِّنَا وَلَا مَبْلَغَ عِلْمِنَا، وَلَا تُسَلِّطْ عَلَيْنَا مَنْ لَا يَرْحَمُنَا', 'عبد الله بن عمر رضي الله عنه', 'صحيح الترمذي', 3502, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 20, 'published'),
  ('189c1d5b-1cbe-4306-ae3e-840d746b3d9c', 'اللَّهُمَّ احْفَظْنِي بِالإِسْلَامِ قَائِمًا، وَاحْفَظْنِي بِالإِسْلَامِ قَاعِدًا، وَاحْفَظْنِي بِالإِسْلَامِ رَاقِدًا، وَلَا تُشْمِتْ بِي عَدُوًّا وَلَا حَاسِدًا، اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ كُلِّ خَيْرٍ خَزَائِنُهُ بِيَدِكَ، وَأَعُوذُ بِكَ مِنْ كُلِّ شَرٍّ خَزَائِنُهُ بِيَدِكَ', 'عبد الله بن مسعود رضي الله عنه', 'صحيح الجامع', 1260, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 21, 'published'),
  ('b7e90b97-78f2-4843-b890-543a97aafbb6', 'اللَّهُمَّ بِعِلْمِكَ الغَيْبَ وَقُدْرَتِكَ عَلَى الخَلْقِ، أَحْيِنِي مَا عَلِمْتَ الحَيَاةَ خَيْرًا لِي، وَتَوَفَّنِي إِذَا عَلِمْتَ الوَفَاةَ خَيْرًا لِي، اللَّهُمَّ إِنِّي أَسْأَلُكَ خَشْيَتَكَ فِي الغَيْبِ وَالشَّهَادَةِ، وَأَسْأَلُكَ كَلِمَةَ الحَقِّ فِي الرِّضَا وَالغَضَبِ، وَأَسْأَلُكَ القَصْدَ فِي الفَقْرِ وَالغِنَى، وَأَسْأَلُكَ نَعِيمًا لَا يَنْفَدُ، وَأَسْأَلُكَ قُرَّةَ عَيْنٍ لَا تَنْقَطِعُ، وَأَسْأَلُكَ الرِّضَى بَعْدَ القَضَاءِ، وَأَسْأَلُكَ بَرْدَ العَيْشِ بَعْدَ المَوْتِ، وَأَسْأَلُكَ لَذَّةَ النَّظَرِ إِلَى وَجْهِكَ، وَالشَّوْقَ إِلَى لِقَائِكَ فِي غَيْرِ ضَرَّاءَ مُضِرَّةٍ، وَلَا فِتْنَةٍ مُضِلَّةٍ، اللَّهُمَّ زَيِّنَّا بِزِينَةِ الإِيمَانِ، وَاجْعَلْنَا هُدَاةً مُهْتَدِينَ', 'عمار بن ياسر رضي الله عنه', 'صحيح الكلم الطيب', 106, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 22, 'published'),
  ('ba6985c7-c8fa-4d05-baa3-e34d4e4a405f', 'رَبِّ أَعِنِّي وَلَا تُعِنْ عَلَيَّ، وَانْصُرْنِي وَلَا تَنْصُرْ عَلَيَّ، وَامْكُرْ لِي وَلَا تَمْكُرْ عَلَيَّ، وَاهْدِنِي وَيَسِّرِ الهُدَى لِي، وَانْصُرْنِي عَلَى مَنْ بَغَى عَلَيَّ، رَبِّ اجْعَلْنِي لَكَ شَكَّارًا، لَكَ ذَكَّارًا، لَكَ رَهَّابًا، لَكَ مِطْوَاعًا، لَكَ مُخْبِتًا، إِلَيْكَ أَوَّاهًا مُنِيبًا، رَبِّ تَقَبَّلْ تَوْبَتِي، وَاغْسِلْ حَوْبَتِي، وَأَجِبْ دَعْوَتِي، وَثَبِّتْ حُجَّتِي، وَسَدِّدْ لِسَانِي، وَاهْدِ قَلْبِي، وَاسْلُلْ سَخِيمَةَ صَدْرِي', 'عبد الله بن عباس رضي الله عنه', 'صحيح الترمذي', 3551, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 23, 'published'),
  ('fc1876bd-d89e-4c8a-8647-d79bbf01cecb', 'اللَّهُمَّ حَاسِبْنِي حِسَابًا يَسِيرًا', 'عائشة رضي الله عنه', 'تخريج مشكاة المصابيح', 5495, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 24, 'published'),
  ('1a07f0b7-a14a-4af6-b3da-2ae0fe0355e1', 'اللَّهُمَّ إِنِّي أَسْأَلُكَ فِعْلَ الخَيْرَاتِ، وَتَرْكَ المُنْكَرَاتِ، وَحُبَّ المَسَاكِينِ، وَإِذَا أَرَدْتَ بِعِبَادِكَ فِتْنَةً فَاقْبِضْنِي إِلَيْكَ غَيْرَ مَفْتُونٍ', 'عبد الله بن عباس رضي الله عنه', 'صحيح الترمذي', 3233, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 25, 'published'),
  ('a8056033-719f-45ea-8f62-b313b0a1e755', 'اللَّهُمَّ إِنِّي عَبْدُكَ، وَابْنُ عَبْدِكَ، وَابْنُ أَمَتِكَ، نَاصِيَتِي بِيَدِكَ، مَاضٍ فِيَّ حُكْمُكَ، عَدْلٌ فِيَّ قَضَاؤُكَ، أَسْأَلُكَ بِكُلِّ اسْمٍ هُوَ لَكَ سَمَّيْتَ بِهِ نَفْسَكَ، أَوْ عَلَّمْتَهُ أَحَدًا مِنْ خَلْقِكَ، أَوْ أَنْزَلْتَهُ فِي كِتَابِكَ، أَوِ اسْتَأْثَرْتَ بِهِ فِي عِلْمِ الغَيْبِ عِنْدَكَ، أَنْ تَجْعَلَ القُرْآنَ رَبِيعَ قَلْبِي، وَنُورَ صَدْرِي، وَجَلَاءَ حُزْنِي، وَذَهَابَ هَمِّي', 'عبد الله بن مسعود رضي الله عنه', 'السلسلة الصحيحة', 199, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 26, 'published'),
  ('7c30d9c3-2c7e-4547-8896-688591fd90f6', 'اللَّهُمَّ مَالِكَ المُلْكِ تُؤْتِي المُلْكَ مَنْ تَشَاءُ، وَتَنْزِعُ المُلْكَ مِمَّنْ تَشَاءُ، وَتُعِزُّ مَنْ تَشَاءُ، وَتُذِلُّ مَنْ تَشَاءُ، بِيَدِكَ الخَيْرُ إِنَّكَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، رَحْمَنَ الدُّنْيَا وَالآخِرَةِ وَرَحِيمَهُمَا، تُعْطِيهِمَا مَنْ تَشَاءُ، وَتَمْنَعُ مِنْهُمَا مَنْ تَشَاءُ، ارْحَمْنِي رَحْمَةً تُغْنِينِي بِهَا عَنْ رَحْمَةِ مَنْ سِوَاكَ', 'أنس بن مالك رضي الله عنه', 'صحيح الترغيب', 1821, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 27, 'published'),
  ('db99b3ea-c7e9-45f8-9139-18bb3ed73fe0', 'اللَّهُمَّ رَبَّ السَّمَوَاتِ السَّبْعِ، وَرَبَّ العَرْشِ العَظِيمِ، رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ، مُنْزِلَ التَّوْرَاةِ وَالإِنْجِيلِ وَالقُرْآنِ، فَالِقَ الحَبِّ وَالنَّوَى، أَعُوذُ بِكَ مِنْ شَرِّ كُلِّ شَيْءٍ أَنْتَ آخِذٌ بِنَاصِيَتِهِ، أَنْتَ الأَوَّلُ فَلَيْسَ قَبْلَكَ شَيْءٌ، وَأَنْتَ الآخِرُ فَلَيْسَ بَعْدَكَ شَيْءٌ، وَأَنْتَ الظَّاهِرُ فَلَيْسَ فَوْقَكَ شَيْءٌ، وَأَنْتَ البَاطِنُ فَلَيْسَ دُونَكَ شَيْءٌ، اقْضِ عَنِّي الدَّيْنَ، وَأَغْنِنِي مِنَ الفَقْرِ', 'أبو هريرة رضي الله عنه', 'صحيح الترمذي', 3481, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 28, 'published'),
  ('fc8c737f-0ec3-4f77-8b55-15fbe36c30cb', 'اللَّهُمَّ إِنِّي أَسْأَلُكَ إِيمَانًا لَا يَرْتَدُّ، وَنَعِيمًا لَا يَنْفَدُ، وَمُرَافَقَةَ مُحَمَّدٍ فِي أَعْلَى جَنَّةِ الخُلْدِ', 'عبد الله بن مسعود رضي الله عنه', 'السلسلة الصحيحة', null, 5, 379, '33333333-3333-4333-8333-000000000001', null, '{}', false, 29, 'published'),
  ('be2baf57-7de4-45c1-b949-6fa5d559c3ac', 'اللَّهُمَّ انْفَعْنِي بِمَا عَلَّمْتَنِي، وَعَلِّمْنِي مَا يَنْفَعُنِي، وَارْزُقْنِي عِلْمًا تَنْفَعُنِي بِهِ', 'أنس بن مالك رضي الله عنه', 'السلسلة الصحيحة', 3151, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 30, 'published'),
  ('3a515dd1-d2d7-4440-97dd-a68f2c178153', 'اللَّهُمَّ اجْعَلْ فِي قَلْبِي نُورًا، وَفِي بَصَرِي نُورًا، وَفِي سَمْعِي نُورًا، وَعَنْ يَمِينِي نُورًا، وَعَنْ يَسَارِي نُورًا، وَفَوْقِي نُورًا، وَتَحْتِي نُورًا، وَأَمَامِي نُورًا، وَخَلْفِي نُورًا، وَاجْعَلْ لِي نُورًا', 'عبد الله بن عباس رضي الله عنه', 'صحيح البخاري', 6316, 8, 69, '33333333-3333-4333-8333-000000000001', 'https://app.turath.io/book/1681/9470', '{}', false, 31, 'published'),
  ('bbc49644-711f-47d1-9e68-ed640c9395cb', 'اللَّهُمَّ أَحْيِنِي مِسْكِينًا، وَأَمِتْنِي مِسْكِينًا، وَاحْشُرْنِي فِي زُمْرَةِ المَسَاكِينِ يَوْمَ القِيَامَةِ', 'أنس بن مالك رضي الله عنه', 'صحيح الترمذي', 2352, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 32, 'published'),
  ('4fffb4cd-6d99-4a57-bea1-6fcbcba0ec50', 'اللَّهُمَّ اسْتُرْ عَوْرَتِي، وَآمِنْ رَوْعَتِي، وَاقْضِ عَنِّي دَيْنِي', 'خباب بن الأرت رضي الله عنه', 'صحيح الجامع', 1262, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 33, 'published'),
  ('2533b1ef-1836-4a02-9ac9-2b7dfa0e8cec', 'اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْمًا كَثِيرًا، وَلَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ، فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِكَ، وَارْحَمْنِي إِنَّكَ أَنْتَ الغَفُورُ الرَّحِيمُ', 'أبو بكر الصديق رضي الله عنه', 'صحيح البخاري', 834, 1, 166, '33333333-3333-4333-8333-000000000001', 'https://app.turath.io/book/1681/1370', '{}', false, 34, 'published'),
  ('bb65b16f-1e04-4ffa-bb05-2d44d9fea637', 'اللَّهُمَّ أَنْتَ رَبِّي، لَا إِلَهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ لَكَ بِذَنْبِي، فَاغْفِرْ لِي، فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ', 'شداد بن أوس رضي الله عنه', 'صحيح البخاري', 6306, 8, 67, '33333333-3333-4333-8333-000000000001', 'https://app.turath.io/book/1681/9452', '{}', false, 35, 'published'),
  ('3c51f9a2-17d0-4adc-a700-85e849ee3a80', 'أَسْتَغْفِرُ اللهَ الَّذِي لَا إِلَهَ إِلَّا هُوَ الحَيُّ القَيُّومُ وَأَتُوبُ إِلَيْهِ', 'عبد الله بن مسعود رضي الله عنه', 'صحيح الترغيب', 1623, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 36, 'published'),
  ('6d7a79b7-38f2-42a6-82c6-fe5fa6045363', 'رَبِّ اغْفِرْ لِي خَطِيئَتِي وَجَهْلِي، وَإِسْرَافِي فِي أَمْرِي كُلِّهِ، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي، اللَّهُمَّ اغْفِرْ لِي خَطَايَايَ وَعَمْدِي وَجَهْلِي وَهَزْلِي، وَكُلُّ ذَلِكَ عِنْدِي، اللَّهُمَّ اغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ، وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ، أَنْتَ المُقَدِّمُ وَأَنْتَ المُؤَخِّرُ، وَأَنْتَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ', 'أبو موسى الأشعري رضي الله عنه', 'صحيح البخاري', 6398, 8, 84, '33333333-3333-4333-8333-000000000001', 'https://app.turath.io/book/1681/9601', '{}', false, 37, 'published'),
  ('6125c2f8-a58e-4553-92aa-81dcf664b5f2', 'اللَّهُمَّ اغْفِرْ لِي ذُنُوبِي وَخَطَايَايَ كُلَّهَا، اللَّهُمَّ أَنْعِشْنِي وَاجْبُرْنِي، وَاهْدِنِي لِصَالِحِ الأَعْمَالِ وَالأَخْلَاقِ؛ فَإِنَّهُ لَا يَهْدِي لِصَالِحِهَا وَلَا يَصْرِفُ سَيِّئَهَا إِلَّا أَنْتَ', 'أبو أمامة الباهلي رضي الله عنه', 'صحيح الجامع', 1266, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 38, 'published'),
  ('219d11a7-0bb5-4c97-b1da-f3f18808ab78', 'اللَّهُمَّ لَكَ أَسْلَمْتُ، وَبِكَ آمَنْتُ، وَعَلَيْكَ تَوَكَّلْتُ، وَإِلَيْكَ أَنَبْتُ، وَبِكَ خَاصَمْتُ، اللَّهُمَّ إِنِّي أَعُوذُ بِعِزَّتِكَ، لَا إِلَهَ إِلَّا أَنْتَ؛ أَلَّا تُضِلَّنِي، أَنْتَ الحَيُّ الَّذِي لَا يَمُوتُ، وَالجِنُّ وَالإِنْسُ يَمُوتُونَ', 'عبد الله بن عباس رضي الله عنه', 'صحيح الجامع', 1309, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 39, 'published'),
  ('ac0396f2-567d-47cb-8544-5ff835881dd2', 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ جَهْدِ البَلَاءِ، وَدَرَكِ الشَّقَاءِ، وَسُوءِ القَضَاءِ، وَشَمَاتَةِ الأَعْدَاءِ', 'أبو هريرة رضي الله عنه', 'صحيح البخاري', 6347, 8, 75, '33333333-3333-4333-8333-000000000001', 'https://app.turath.io/book/1681/9519', '{}', false, 40, 'published'),
  ('8e4ce646-65c6-485d-a853-16c7439cd7a3', 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الهَمِّ وَالحَزَنِ، وَالعَجْزِ وَالكَسَلِ، وَالبُخْلِ وَالجُبْنِ، وَضَلَعِ الدَّيْنِ، وَغَلَبَةِ الرِّجَالِ', 'أنس رضي الله عنه', 'صحيح البخاري', 2893, 4, 35, '33333333-3333-4333-8333-000000000001', 'https://app.turath.io/book/1681/4590', '{}', false, 41, 'published'),
  ('540746be-4e2b-417d-b63a-b21cacb1e60a', 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ مَا عَمِلْتُ، وَمِنْ شَرِّ مَا لَمْ أَعْمَلْ', 'عائشة رضي الله عنه', 'صحيح مسلم', 2716, 4, 2085, '33333333-3333-4333-8333-000000000001', 'https://app.turath.io/book/1727/6829', '{}', false, 42, 'published'),
  ('c4550013-bb31-4e3c-8bda-0b047c644682', 'اللَّهُمَّ أَعُوذُ بِرِضَاكَ مِنْ سَخَطِكَ، وَبِمُعَافَاتِكَ مِنْ عُقُوبَتِكَ، وَأَعُوذُ بِكَ مِنْكَ، لَا أُحْصِي ثَنَاءً عَلَيْكَ أَنْتَ كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ', 'عائشة رضي الله عنه', 'صحيح مسلم', 486, 1, 352, '33333333-3333-4333-8333-000000000001', 'https://app.turath.io/book/1727/1037', '{}', false, 43, 'published'),
  ('ca769cb6-105c-40e8-accc-a32095e87942', 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ زَوَالِ نِعْمَتِكَ، وَتَحَوُّلِ عَافِيَتِكَ، وَفُجَاءَةِ نِقْمَتِكَ، وَجَمِيعِ سَخَطِكَ', 'عبد الله بن عمر رضي الله عنه', 'صحيح مسلم', 2739, 4, 2097, '33333333-3333-4333-8333-000000000001', 'https://app.turath.io/book/1727/6877', '{}', false, 44, 'published'),
  ('f4e910cc-1429-42e6-8735-6225e3b009bd', 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ البُخْلِ، وَأَعُوذُ بِكَ مِنَ الجُبْنِ، وَأَعُوذُ بِكَ مِنْ أَنْ نُرَدَّ إِلَى أَرْذَلِ العُمُرِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الدُّنْيَا، وَعَذَابِ القَبْرِ', 'سعد بن أبي وقاص رضي الله عنه', 'صحيح البخاري', 6390, 8, 83, '33333333-3333-4333-8333-000000000001', 'https://app.turath.io/book/1681/9589', '{}', false, 45, 'published'),
  ('c12292a1-3b97-4397-9b71-2fae8aaa472a', 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ العَجْزِ، وَالكَسَلِ، وَالجُبْنِ، وَالبُخْلِ، وَالهَرَمِ، وَعَذَابِ القَبْرِ، اللَّهُمَّ آتِ نَفْسِي تَقْوَاهَا، وَزَكِّهَا أَنْتَ خَيْرُ مَنْ زَكَّاهَا، أَنْتَ وَلِيُّهَا وَمَوْلَاهَا، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عِلْمٍ لَا يَنْفَعُ، وَمِنْ قَلْبٍ لَا يَخْشَعُ، وَمِنْ نَفْسٍ لَا تَشْبَعُ، وَمِنْ دَعْوَةٍ لَا يُسْتَجَابُ لَهَا', 'زيد بن أرقم رضي الله عنه', 'صحيح مسلم', 2722, 4, 2088, '33333333-3333-4333-8333-000000000001', 'https://app.turath.io/book/1727/6840', '{}', false, 46, 'published'),
  ('89546025-629d-49f2-bc8e-4d9904986276', 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ سَمْعِي، وَمِنْ شَرِّ بَصَرِي، وَمِنْ شَرِّ لِسَانِي، وَمِنْ شَرِّ قَلْبِي، وَمِنْ شَرِّ مَنِيِّي', 'شكل بن حميد العبسي رضي الله عنه', 'صحيح الجامع', 4399, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 47, 'published'),
  ('7c88ed84-81d4-4cec-9a54-9ac93b50162b', 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الهَدْمِ، وَأَعُوذُ بِكَ مِنَ التَّرَدِّي، وَأَعُوذُ بِكَ مِنَ الغَرَقِ وَالحَرَقِ وَالهَرَمِ، وَأَعُوذُ بِكَ أَنْ يَتَخَبَّطَنِي الشَّيْطَانُ عِنْدَ المَوْتِ، وَأَعُوذُ بِكَ أَنْ أَمُوتَ فِي سَبِيلِكَ مُدْبِرًا، وَأَعُوذُ بِكَ أَنْ أَمُوتَ لَدِيغًا', 'كعب بن عمرو رضي الله عنه', 'صحيح أبي داود', 1552, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 48, 'published'),
  ('274c67f1-add8-496e-906d-38c3947484c3', 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ فِتْنَةِ النَّارِ وَعَذَابِ النَّارِ، وَفِتْنَةِ القَبْرِ وَعَذَابِ القَبْرِ، وَشَرِّ فِتْنَةِ الغِنَى وَشَرِّ فِتْنَةِ الفَقْرِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ فِتْنَةِ المَسِيحِ الدَّجَّالِ، اللَّهُمَّ اغْسِلْ قَلْبِي بِمَاءِ الثَّلْجِ وَالبَرَدِ، وَنَقِّ قَلْبِي مِنَ الخَطَايَا كَمَا نَقَّيْتَ الثَّوْبَ الأَبْيَضَ مِنَ الدَّنَسِ، وَبَاعِدْ بَيْنِي وَبَيْنَ خَطَايَايَ كَمَا بَاعَدْتَ بَيْنَ المَشْرِقِ وَالمَغْرِبِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الكَسَلِ، وَالمَأْثَمِ وَالمَغْرَمِ', 'عائشة رضي الله عنه', 'صحيح البخاري', 6377, 8, 81, '33333333-3333-4333-8333-000000000001', 'https://app.turath.io/book/1681/9568', '{}', false, 49, 'published'),
  ('9c0c8892-0446-47f3-bb2d-1179a95261de', 'اللَّهُمَّ رَبَّ جَبْرَائِيلَ وَمِيكَائِيلَ، وَرَبَّ إِسْرَافِيلَ، أَعُوذُ بِكَ مِنْ حَرِّ النَّارِ، وَمِنْ عَذَابِ القَبْرِ', 'عائشة رضي الله عنه', 'صحيح النسائي', 5534, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 50, 'published')
